var KB_HERBS_EXTRA = [{"cat":"发散风寒药","caution":"","classic":"附药：紫苏梗  本品为唇形科植物紫苏Perilla frutescens （L.）Britt.的干燥茎。性味辛，温；归肺、脾经。功能理气宽中，止痛，安胎。适用于胸膈痞闷，胃脘疼痛，嗳气呕吐，胎动不安。煎服，5～10g。","dosage":"5～10g","effect":"理气宽中，止痛，安胎","name":"紫苏梗","nature":"辛，温；归肺、脾经","parent":"紫苏叶","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～10g"},{"cat":"发散风寒药","caution":"","classic":"本品为姜科植物姜Zingiber officinale Rosc.的根茎切下的外表皮。性味辛、凉。功能和脾行水消肿，主要用于水肿，小便不利。煎服，3～10g。  ","dosage":"3～10g","effect":"和脾行水消肿，主要用于水肿，小便不利","name":"生姜皮","nature":"辛、凉","parent":"生姜","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～10g"},{"cat":"发散风寒药","caution":"","classic":"本品系用生姜捣汁入药。功同生姜，但偏于开痰止呕，便于临床应急服用。如遇天南星、半夏中毒的喉舌麻木肿痛，或呕逆不止、难以下食者，可取汁冲服，易于入喉；也可配竹沥，冲服或鼻饲给药，治中风卒然昏厥者。用量3～10滴，冲服。","dosage":"","effect":"","name":"生姜汁","nature":"","parent":"生姜","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"用量3～10滴，冲服"},{"cat":"发散风寒药","caution":"","classic":"附药：荆芥炭  本品为荆芥的炮制加工品。取荆芥段照炒炭法炒至表面焦黑色，内部焦黄色，喷淋清水少许，熄灭火星，取出，晾干。性味辛、涩，微温；归肺、肝经。功能收敛止血。适用于便血、崩漏、产后血晕。煎服，5～10g。","dosage":"5～10g","effect":"收敛止血","name":"荆芥炭","nature":"辛、涩，微温；归肺、肝经","parent":"荆芥","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～10g"},{"cat":"发散风寒药","caution":"","classic":"附药：苍耳草  本品为菊科植物苍耳Xanthium sibiricum Patr.的茎叶。性味苦、辛、微寒；有小毒。功能祛风，清热，解毒。主要用治风湿痹痛，四肢拘急等症。也可用于麻风、疔毒、皮肤瘙痒诸证。本品有毒，内服不宜过量，亦不能持续服用。用量6～15g，水煎或熬膏及入丸散。外用适量。本品散气耗血，体虚者慎用。","dosage":"6～15g","effect":"祛风，清热，解毒","name":"苍耳草","nature":"苦、辛、微寒；有小毒","parent":"苍耳子","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"用量6～15g，水煎或熬膏及入丸散"},{"cat":"发散风寒药","caution":"热毒壅盛而疹出不畅者忌服。   ","classic":"1.麻疹不透 本品辛温香散，能发散风寒，透疹外达，用治风寒束表，疹发不畅，或疹出而又复隐者，可单用煎汤局部熏洗，或与荆芥、薄荷等解表透疹药同用。亦可用于风寒感冒，恶寒发热者，因其发汗解表之力较弱，故临床少用。   2.饮食不消，纳食不佳 本品气味芳香，能开胃消食，增进食欲，尤多用于饮食调味。若治疗饮食积滞，胃纳不佳者，可与健脾消食药、行气和中药同用。   ","dosage":"3～6g","effect":"发表透疹，开胃消食。   ","name":"胡荽","nature":"辛，温。归肺、胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g。外用适量。   "},{"cat":"发散风寒药","caution":"麻疹已透者不宜使用。用量过大易致心烦、呕吐。   ","classic":"1.麻疹不透，风疹瘙痒 本品辛散透发，功专发表透疹，主治麻疹初起，疹出不畅，或表邪外束，疹毒内陷，始见形而骤然收没者，常配伍牛蒡子、蝉蜕、竹叶等透疹药同用，如竹叶柳蒡汤（《医学广笔记》）。亦可煎汤熏洗、擦摩。此外，本品煎汤沐浴治风疹瘙痒，也可配伍防风、荆芥、薄荷等祛风止痒药。   2.风湿痹痛 本品辛散，有祛风除湿作用，治疗风湿痹证，肢节疼痛，可与羌活、独活、秦艽等祛风湿、止痹痛药同用。   ","dosage":"3～6g","effect":"发表透疹，祛风除湿。   ","name":"西河柳","nature":"甘、辛，平。归肺、胃、心经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g。外用适量，煎汤擦洗。   "},{"cat":"发散风热药","caution":"","classic":"附药：葛花  本品为豆科植物野葛Pueraria lobata （Willd.）Ohwi或甘葛藤Pueraria thomsonii Benth.的未开放花蕾。性味甘，平。功能解酒毒，醒脾和胃。主要用于饮酒过度，头痛头昏、烦渴、呕吐、胸膈饱胀等症。常用量3～15g。","dosage":"3～15g","effect":"解酒毒，醒脾和胃","name":"葛花","nature":"甘，平","parent":"葛根","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"用量3～15g"},{"cat":"发散风热药","caution":"","classic":"附药：大豆黄卷  本品为豆科植物大豆Glycine max （L.） Merr. 的成熟种子经发芽干燥的炮制加工品。性味甘，平；归脾、胃、肺经。功能解表祛暑，清热利湿。适用于暑湿感冒，湿温初起，发热汗少，胸闷脘痞，肢体酸重，小便不利。煎服，9～15g。","dosage":"9～15g","effect":"解表祛暑，清热利湿","name":"大豆黄卷","nature":"甘，平；归脾、胃、肺经","parent":"淡豆豉","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～15g"},{"cat":"发散风热药","caution":"表虚自汗者不宜使用。   ","classic":"1.风热感冒 本品辛寒，质轻上浮，有宣肺发汗，疏散风热之功，较宜于风热感冒，发热无汗等症，可与薄荷、蝉蜕、连翘等同用。若风寒感冒，恶寒无汗，亦可与麻黄、香薷、羌活等发散风寒药同用。   2.麻疹不透 本品辛散，能疏散风热，解表透疹。用于麻疹初起，疹出不畅，常与薄荷、蝉蜕、牛蒡子等同用。   3.风疹瘙痒 本品辛散，具有祛风止痒之功，可用治风邪郁闭肌表，风疹瘙痒。偏于风热者，多与蝉蜕、薄荷、牛蒡子等辛凉类疏风止痒药同用；偏于风寒者，多与麻黄、防风、荆芥等辛温类祛风止痒药同用。   4.水肿尿少 本品上可开宣肺气而发汗透邪，下可通调水道而利尿消肿，故以治疗水肿尿少兼风热表证者为宜，可单用，或与麻黄、连翘、冬瓜皮等同用。   ","dosage":"3～9g","effect":"宣散风热，透疹止痒，利尿消肿。   ","name":"浮萍","nature":"辛，寒。归肺、膀胱经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g。外用适量，煎汤浸洗。   "},{"cat":"发散风热药","caution":"","classic":"1.风热目赤，迎风流泪，目生云翳 本品功能疏散风热，明目退翳，较少用于一般风热感冒，而主要用于风热上攻于目，目赤肿痛，多泪，目生翳障，常与蝉蜕、谷精草、菊花等疏散风热、明目退翳药同用。若肝热目赤，可与决明子、夏枯草、菊花等清肝明目药配伍。   2.出血证 本品兼有止血作用，但药力薄弱，较少单独使用，宜与其他止血药配伍治疗出血证。如治疗肠风下血，可与地榆、槐角、荆芥等配伍；治疗外伤出血，用本品配伍三七、黄柏、五倍子等药。   ","dosage":"3～9g","effect":"疏散风热，明目退翳。   ","name":"木贼","nature":"甘、苦，平。归肺、肝经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g。   "},{"cat":"发散风热药","caution":"阴虚血亏之眼疾者不宜用。   ","classic":"1.风热目赤，肿痛羞明，目生翳膜 本品味辛质轻升散，善于疏散头面风热，明目退翳，用治风热上攻之目赤肿痛，羞明多泪，目生翳膜者，常与荆芥、决明子、龙胆草等同用。   2.风热头痛 本品有疏散风热，止痛作用，治疗风热头痛，可与薄荷、菊花、牛蒡子等同用。   ","dosage":"5～10g","effect":"疏散风热，明目退翳。   ","name":"谷精草","nature":"辛、甘，平。归肝、肺经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～10g。   "},{"cat":"清热泻火药","caution":"脾胃虚寒者慎用。   ","classic":"1.热病烦渴，癫狂 本品性寒，入心经能清热泻火，清心除烦，入胃经能清泻胃火以止渴，治温热病邪在气分，壮热烦渴者，常与石膏、滑石等同用，如三石汤（《温病条辨》）。取本品清泻心胃经实火，用治伤寒阳明热盛之癫狂，常与黄连、甘草等同用；若与天竺黄、冰片等清热化痰、开窍醒神药配伍，可治痰热躁狂。   2.口舌生疮，热毒疮肿，丹毒，烧烫伤 本品能清热泻火以消肿止痛。治疗口舌生疮，可与黄柏等分为末，撒敷患处；若治热毒疮肿，可用本品火煅，配青黛等分为末，香油调搽；若治烧烫伤，可配赤石脂等分为末，菜油调敷，破烂有水者，取药末撒患处；若小儿丹毒，可用本品研末，水调和猪胆汁涂之。   ","dosage":"9～15g","effect":"清热泻火。   ","name":"寒水石","nature":"辛、咸，寒。归心、胃、肾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～15g。打碎先煎。外用适量，研细粉调敷患处。   "},{"cat":"清热泻火药","caution":"脾胃虚弱者用量宜小。   ","classic":"1.热病烦渴，风热感冒 本品性寒，功能清热泻火。治热入气分，高热烦渴，可与石膏、知母、芦根等同用，以加强清热泻火作用。治风热感冒，常与金银花、薄荷、菊花等同用，以加强疏散风热之功。   2.咽喉肿痛，痈肿疔毒 本品能清热解毒利咽，治咽喉肿痛，常与板蓝根、玄参、山豆根等同用；治痈肿疔毒，常与紫花地丁、野菊花、蒲公英等同用，或以鲜品捣烂外敷。   3.水肿尿少，热淋涩痛 本品甘淡性寒，既能淡渗利水以消肿，又能清泄湿热以通淋，治疗湿热水肿尿少，小便淋沥涩痛，可与车前草、木通、白茅根等药同用。   ","dosage":"15～30g","effect":"清热泻火，解毒，利水消肿。   ","name":"鸭跖草","nature":"甘、淡，寒。归肺、胃、小肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～30g。外用适量。   "},{"cat":"清热泻火药","caution":"","classic":"1.目赤肿痛，羞明多泪，目生翳膜 本品甘寒，入肝经能清泻肝火，明目退翳，治肝火上炎之目赤肿痛，常与夏枯草、决明子等同用；治风热上攻之羞明多泪，常与木贼、菊花等同用；治肝火郁滞，目生翳膜，常与蝉蜕、白蒺藜等同用，如拨云退翳丸（《原机启微》）。   2.肝虚目暗，视物昏花 本品甘寒质润，入肝经，既能清肝明目，又兼能养肝明目，治肝虚有热所致目暗不明，视物昏花者，常与菟丝子、女贞子等同用。   ","dosage":"3～9g","effect":"清热泻火，养肝明目，退翳。   ","name":"密蒙花","nature":"甘，微寒。归肝经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g。   "},{"cat":"清热泻火药","caution":"本品有扩散瞳孔作用，青光眼患者禁用。   ","classic":"1.肝热目赤，目生翳膜，视物昏花 本品苦寒清降，功专清泻肝火，明目退翳。用治肝火上炎之目赤肿痛，目生翳膜，常与决明子、茺蔚子、羚羊角等同用；治肝虚血热之视物昏花，常与熟地黄、玄参、车前子等同用。   2.肝火眩晕 本品能清泻肝火以平抑肝阳，治肝阳化火所致头痛、眩晕、烦躁不寐，可与石决明、栀子、夏枯草等药同用。   ","dosage":"9～15g","effect":"清肝泻火，明目退翳。   ","name":"青葙子","nature":"苦，微寒。归肝经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～15g。   "},{"cat":"清热燥湿药","caution":"脾胃虚寒者忌用，阴虚津伤者慎用。   ","classic":"1.湿热黄疸，阴肿阴痒，带下，湿疹瘙痒 本品苦寒，清热燥湿之中，尤善清下焦湿热，常用治下焦湿热所致诸证。治湿热黄疸，常与苦参同用，如苦参丸（《杂病源流犀烛》）；或与栀子、大黄、白茅根等药同用；若治湿热下注，带下黄臭、阴肿阴痒、湿疹瘙痒，常配泽泻、木通、车前子等药，如龙胆泻肝汤（《兰室秘藏》）。   2.肝火头痛，目赤肿痛，耳鸣耳聋，胁痛口苦，强中，惊风抽搐 本品苦寒沉降，善泻肝胆实火。治肝火头痛，目赤肿痛，耳鸣耳聋，强中，胁痛口苦，常配伍柴胡、黄芩、栀子等药，如龙胆泻肝汤（《兰室秘藏》）；治肝经热盛，热极生风所致之高热惊风抽搐，常配伍牛黄、黄连、钩藤等药，如凉惊丸（《小儿药性直诀》），或与大黄、芦荟、青黛等药同用，如当归龙荟丸（《宣明论方》）。   ","dosage":"3～6g","effect":"清热燥湿，泻肝胆火。   ","name":"龙胆","nature":"苦，寒。归肝、胆经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g。   "},{"cat":"清热解毒药","caution":"","classic":"本品为忍冬科植物忍冬Lonicera japonica Thund.的干燥茎枝，又名金银花藤。性味甘，寒；归肺、胃经。功用与金银花相似，但清热解毒之力不及金银花，兼有清热疏风、通络止痛的功效，临床多用于温病发热、风湿热痹等证。煎服，9～30g。  ","dosage":"9～30g","effect":"","name":"忍冬藤","nature":"甘，寒；归肺、胃经","parent":"金银花","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～30g"},{"cat":"清热解毒药","caution":"","classic":"本品为忍冬科植物灰毡毛忍冬Lonicera macranthoides Hand.-Mazz.、红腺忍冬Lonicera hypoglauca Miq.、华南忍冬Lonicera confusa DC.或黄褐毛忍冬Lonicera fulvotomentosa Hsu et S.C.Cheng的干燥花蕾或带初开的花。主产于重庆、贵州、湖南、广西。夏初花开放前采收，干燥，生用。性味甘，寒；归肺、心、胃经。功能清热解毒，疏散风热。适用于痈肿疔疮，喉痹，丹毒，风热感冒，温病发热。本品药性功用与金银花相似，在有些地区作为金银花的代用品使用。煎服，6～15g。","dosage":"6～15g","effect":"清热解毒，疏散风热","name":"山银花","nature":"甘，寒；归肺、心、胃经","parent":"金银花","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，6～15g"},{"cat":"清热解毒药","caution":"本品有小毒，用量不宜过大。服用本品时忌油腻。脾胃虚寒者及孕妇慎用。   ","classic":"1.时疫感冒，风热头痛，温毒发斑 本品苦寒，善解时疫之毒，既能清气分之实热，又能解血分之热毒，可用于防治温热毒邪所致之证。治疗时疫感冒，风热头痛，可与薄荷、金银花、板蓝根等药同用。治温热病热入营血，或温毒发斑，常与玄参、大青叶、水牛角等药配伍。   2.痄腮，疮疡肿毒 本品苦寒，有清热凉血解毒之功，治痄腮红肿疼痛，疮疡肿毒，可与牛蒡子、连翘、青黛等药同用。   3.虫积腹痛 本品能“杀三虫”，与驱虫药配伍用于绦虫、钩虫、蛲虫、蛔虫等多种肠道寄生虫病。   4.崩漏下血 本品炒炭有收涩止血之功，主治血热所致之衄血、吐血、便血、崩漏等，尤善治崩漏下血。治崩漏下血，可与五灵脂、茜草等同用；治衄血吐血，可配伍黄连、白及等；治便血，可配伍地榆、槐花等药。   ","dosage":"5～10g","effect":"清热解毒，驱虫，止血。   ","name":"贯众","nature":"苦，微寒；有小毒。归肝、胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～10g。清热解毒、驱虫宜生用；止血宜炒炭用。外用适量。   "},{"cat":"清热解毒药","caution":"无实火热毒者不宜用。   ","classic":"1.痈肿瘰疬，蛇虫咬伤，口舌生疮 本品苦泄寒凉，能清热解毒，消肿散结。治疮痈肿痛、瘰疬、痔疮、烧烫伤、毒蛇咬伤等证，可以鲜品捣烂敷患处，或煎汤外洗，或配重楼、紫花地丁等药同用。治口舌生疮，可与板蓝根、黄连、栀子等药同用。   2.热病神昏，惊痫抽搐 本品苦寒入肝经，息风止痉。治热病高热神昏，惊痫抽搐以及破伤风等，常配伍钩藤、全蝎、僵蚕等药。   3.赤痢热泻 本品既能清热解毒，又能凉血止痢，且兼涩肠止泻之功，治赤痢脓血，湿热泄泻，可单用或与银花炭、白头翁、秦皮等同用。   4.血热出血，痔疮出血 本品苦微寒，入肝经血分而能凉血止血。治血热妄行所致的吐血、衄血、崩漏等出血证，常与贯众、白茅根、大蓟等同用。若便血、痔血者，可与地榆、槐花等药配伍。   5.肺热咳嗽 本品苦寒，取其清肺热、解热毒之功，也用治肺热咳嗽，可与黄芩、桑白皮、马兜铃等药配伍。   ","dosage":"5～10g","effect":"清热解毒，消肿，息风定惊，止血。   ","name":"拳参","nature":"苦、涩，微寒。归肺、肝、大肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～10g。外用适量。   "},{"cat":"清热解毒药","caution":"孕妇慎用。   ","classic":"1.乳痈肿痛，痈疽发背，瘰疬疮毒 本品苦寒降泄，功能清热解毒、消痈散结，又兼通经下乳之功，故为治乳痈良药。治乳痈肿痛，可与蒲公英、瓜蒌等同用；治热毒壅聚，痈疽发背，常与大黄、连翘、紫花地丁等同用；治痰火郁结，瘰疬欲破者，可与海藻、玄参、连翘等同用；《本草汇言》用本品与荆芥、苦参、白鲜皮等药浸酒蒸饮，治疗湿疹湿疮、皮肤瘙痒等。   2.乳汁不通 本品味苦降泄，有通经下乳之功，为产后乳汁不通的常用药。治乳络壅滞，乳汁不下，乳房胀痛，欲作乳痈者，常与穿山甲、王不留行等药同用；若为气血亏虚，乳少清稀者，当配伍黄芪、鹿角胶等同用。   3.湿痹拘挛 本品性善通利，有舒筋活络通脉之功。治湿痹筋脉拘挛，骨节疼痛，常与木瓜、地龙等配伍。   ","dosage":"5～9g","effect":"清热解毒，消痈散结，通经下乳，舒筋通脉。   ","name":"漏芦","nature":"苦，寒。归胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～9g。外用，研末调敷，或煎水洗。   "},{"cat":"清热解毒药","caution":"","classic":"1.肺痈吐脓，肺热喘咳 本品辛凉，既可清热解毒，又善排脓祛瘀，并能清肺化痰，善治肺痈咯痰浓稠腥臭或咳吐脓血。治肺痈，可单用，或与鱼腥草、金银花、芦根等配伍；治肺热咳嗽，可与天花粉、射干等同用。   2.瘰疬疮疖，乳蛾肿痛 本品凉以清热，辛以散结，有解毒、消痈、利咽、消肿之效。治瘰疬痰核，可与生何首乌等药配伍；治疮痈疖肿或毒蛇咬伤，可配蒲公英、紫花地丁等药；治乳蛾肿痛，可与射干、山豆根、马勃等同用。  此外，本品尚有健脾消食之功，与茯苓、麦芽等同用，可用治疳积消瘦，腹胀食少等证。   ","dosage":"15～45g","effect":"清热解毒，排脓祛瘀。   ","name":"金荞麦","nature":"微辛、涩，凉。归肺经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～45g，用水或黄酒隔水密闭炖服。   "},{"cat":"清热解毒药","caution":"","classic":"附药：墓头回  本品为败酱科植物异叶败酱Patrinia heterophylla Bunge及糙叶败酱Patrinia seabra Bunge的根。主产于山西、河南、河北等地。秋季采挖，去净茎苗，晒干。味辛、苦，性微寒。效用与败酱草相似，兼有止血、止带的功效，多用于治疗崩漏下血、赤白带下等证。用法用量、使用注意同败酱草。","dosage":"","effect":"","name":"墓头回","nature":"","parent":"败酱草","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"用量、使用注意同败酱草"},{"cat":"清热解毒药","caution":"","classic":"附药：北豆根  本品为防己科植物蝙蝠葛Menispermum dauricum DC.的干燥根茎。春、秋两季采挖，除去须根和泥土，干燥，切片生用，为北方地区所习用。本品性味苦寒，有小毒；归肺、胃、大肠经。功能清热解毒，祛风止痛。用于热毒壅盛，咽喉肿痛，热毒泄痢及风湿痹痛。煎服，3～9g。本品用量不宜过大，脾胃虚寒者不宜使用。","dosage":"3～9g","effect":"清热解毒，祛风止痛","name":"北豆根","nature":"苦寒，有小毒；归肺、胃、大肠经","parent":"山豆根","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g"},{"cat":"清热解毒药","caution":"风寒袭肺之咳嗽、失音者不宜使用。   ","classic":"1.风热郁肺，咽痛音哑，咳嗽 本品味辛质轻，入肺经。既能宣散肺经风热，又能清泻肺经实火，长于解毒利咽，为治咽喉肿痛的常用药。因其性平，故不论热毒、风热或虚火上炎所致的咽喉肿痛均可选用，而尤宜于风热郁肺者。治风热及肺火所致咽喉肿痛、咳嗽、失音，常与牛蒡子、玄参、板蓝根等同用，如普济消毒饮（《东垣试效方》）。配伍生地黄、玄参、知母等药，也可用治肺肾阴虚所致的咽喉肿痛。本品清肺止咳、利咽开音，可用治肺热咳嗽，声音嘶哑，常与黄芩、蝉蜕、射干等药同用。   2.衄血，创伤出血 本品外用有止血作用。治疗衄血，外伤出血，可用马勃粉撒敷患处。此外，内服也有清热凉血止血之功，用治火邪迫肺，血热妄行引起的吐血、衄血，可单用，或与其他凉血止血药配伍使用。   ","dosage":"2～6g","effect":"清肺，解毒利咽，止血。   ","name":"马勃","nature":"辛，平。归肺经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，2～6g。外用适量，敷患处。   "},{"cat":"清热解毒药","caution":"","classic":"1.咽喉肿痛，咳嗽痰稠，烦热口渴 本品味甘酸以化阴，性平偏凉以清热，功能清热解毒，生津利咽，略兼化痰之功。用治风热上袭或热毒蕴结而致咽喉肿痛，常与硼砂、冰片、青黛等同用；若用治咽干口燥，烦渴音哑，咳嗽痰黏，可单用鲜品熬膏服用，亦可与金银花、桔梗、芦根等同用。   2.鱼蟹中毒 本品味甘，能解鱼蟹毒。如《随息居饮食谱》中单用鲜品榨汁或煎浓汤饮用，用于进食河豚中毒。  此外，本品有一定的醒酒作用，《本草汇言》单用青果十枚，煎汤饮服，用于饮酒过度。   ","dosage":"5～10g","effect":"清热解毒，利咽，生津。   ","name":"青果","nature":"甘、酸，平。归肺、胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～10g。   "},{"cat":"清热解毒药","caution":"","classic":"附药：西青果  本品为使君子科植物诃子Terminalia chebula Retz.的干燥幼果。又称藏青果。性味苦、酸、涩，平；归肺、大肠经。功能清热生津，解毒。适用于阴虚白喉。煎服，1.5～3g。","dosage":"5～3g","effect":"清热生津，解毒","name":"西青果","nature":"苦、酸、涩，平；归肺、大肠经","parent":"青果","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，1.5～3g"},{"cat":"清热解毒药","caution":"","classic":"1.肺热咳嗽，喉痹音哑 本品苦甘凉，具有清肺热、利咽喉之功效，为治咽喉肿痛之常用药，尤多用治音哑。治疗邪热伤阴，咽喉肿痛，声音嘶哑，多与玄参、麦冬、冰片等配伍。本品又具清肺化痰止咳之功，用治肺热咳嗽，或小儿百日咳，常与桔梗、桑白皮、款冬花等同用。   2.肝胃气痛 本品甘缓苦泄，入肝、胃经，能疏肝和胃止痛，治疗肝郁气滞，肝胃气痛，脘腹、胁肋胀痛等，《本草纲目拾遗》单用本品研末，酒调送服。   ","dosage":"1～3g","effect":"清肺利咽，疏肝和胃。   ","name":"木蝴蝶","nature":"苦、甘，凉。归肺、肝、胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，1～3g。   "},{"cat":"清热解毒药","caution":"本品对胃肠道及肝肾均有损害，内服需严格控制剂量，不宜多用久服。外用注意用胶布保护好周围正常皮肤，以防止对正常皮肤的刺激。孕妇及小儿慎用。胃肠出血及肝肾病患者不宜使用。   ","classic":"1.热毒血痢，冷积久痢 本品苦寒，能清热解毒，尤善清大肠蕴热，凉血止痢，故可用治热毒血痢，大便脓血，里急后重。如《医学衷中参西录》单用本品去皮，白糖水送服。本品又有燥湿杀虫止痢之功，用治冷积久痢，可采取口服与灌肠并用的方法；若用治久痢久泻，迁延不愈者，可与诃子、乌梅、木香等同用。   2.疟疾 本品苦寒入肝经，能清肝胆湿热，有杀虫截疟之功，故可用于各种类型的疟疾，尤以间日疟及三日疟疗效最佳，对恶性疟疾也有效。   3.赘疣鸡眼 本品外用有腐蚀作用。用治赘疣、鸡眼，可取鸦胆子仁捣烂涂敷患处，或用鸦胆子油局部涂敷。治疗鸡眼，可以鸦胆子仁，同白酒捣烂敷患处，外用胶布固定；《医学衷中参西录》亦用上法治赘疣。   ","dosage":"5～2g","effect":"清热解毒，止痢，截疟；外用腐蚀赘疣。   ","name":"鸦胆子","nature":"苦，寒；有小毒。归大肠、肝经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"内服，0.5～2g，用龙眼肉包裹或装入胶囊吞服，亦可压去油制成丸剂、片剂服，不宜入煎剂。外用适量。   "},{"cat":"清热解毒药","caution":"","classic":"1.热泻热痢 本品有清热解毒止痢，凉血止血之功效，故常用于湿热、热毒所致的泻痢不止、大便脓血。治湿热泻痢，如《经验方》以本品研末，米汤送服；若用治血痢、大便脓血者，可与马齿苋、地榆等配伍以增强疗效。   2.血热出血 本品既能凉血止血，又能活血散瘀，具有止血而不留瘀的特点，故用于血热所致的咳血、衄血、便血、尿血、痔血、崩漏以及外伤出血。治血热之咳血、衄血，可与生地黄、牡丹皮、赤芍等配伍；治便血、痔血，可与地榆、槐花等配用；治妇女崩漏，《世医得效方》单用为末，姜、酒调服；若治外伤肿痛出血，可取鲜品捣烂，外敷患处。本品既能止血，又能利尿通淋，可治疗尿血、血淋，常与白茅根、小蓟等同用。   3.湿热黄疸 本品既能清热解毒，又能利湿退黄。可单用本品煎服，治疗湿热黄疸，小便不利，或与茵陈、栀子、黄柏等同用。   4.疮疖痈肿，蛇虫咬伤 本品既能清热解毒，又具凉血消肿之功，故可用于热毒所致之疮疖痈肿、蛇虫咬伤等证，常取鲜品捣烂外敷患处。   ","dosage":"9～20g","effect":"清热解毒，凉血止血，利湿退黄。   ","name":"地锦草","nature":"辛，平。归肝、大肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～20g；鲜品30～60g。外用适量。   "},{"cat":"清热解毒药","caution":"水肿属阴水者忌用。   ","classic":"1.痈肿疔疮，蛇虫咬伤 本品有较好的清热解毒作用，是治疗热毒所致疮痈肿痛之常用药。内服外用均可，尤以鲜品捣烂外敷为佳。治疗疔疮肿毒、乳痈肿痛，可单用鲜品捣烂外敷患处；或配伍金银花、蒲公英、野菊花等药；若用于毒蛇咬伤、蜂蝎螫伤，常与白花蛇舌草、重楼、紫花地丁等同用。   2.鼓胀水肿，湿热黄疸 本品有利尿消肿之功，故可用治鼓胀、水肿、小便不利。如治疗水湿停蓄，大腹水肿，可与金钱草、大黄等药配伍；用于湿热黄疸，小便不利，与茵陈、泽泻、栀子等配伍。   3.湿疹湿疮 本品既有清热解毒作用，又兼有利水祛湿之功，对皮肤湿疮湿疹及手足疥癣均有较好疗效。可单味水煎或配伍苦参、蛇床子、白鲜皮等药，局部湿敷或外搽患处。   ","dosage":"9～15g","effect":"清热解毒，利尿消肿。   ","name":"半边莲","nature":"辛，平。归心、小肠、肺经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～15g；鲜品30～60g。外用适量。   "},{"cat":"清热解毒药","caution":"体虚者慎用。   ","classic":"1.痈肿疔毒，瘰疬痰核，蛇虫咬伤 本品味辛能散，寒能清热，故有清热解毒，化痰，消痈散结之效。治疗痈疽发背，疔疮肿毒，瘰疬痰核，蛇虫咬伤，与雄黄、朱砂、麝香等解毒疗疮药配用，内服外用均可，如紫金锭（《百一选方》）。   2.癥瘕痞块 本品有解毒消肿、化痰散结之功，近年来本品广泛地用于癥瘕痞块和多种肿瘤。如治疗肝硬化，以本品配伍土鳖虫、穿山甲、蝼蛄等同用，对软化肝脾，恢复肝功，有明显效果；若与丹参、浙贝母、夏枯草等制成复方，对甲状腺瘤有较好疗效。  此外，本品尚有化痰作用，可用治风痰癫痫。   ","dosage":"3～9g","effect":"清热解毒，化痰散结。   ","name":"山慈菇","nature":"甘、微辛，凉。归肝、脾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g。外用适量。   "},{"cat":"清热解毒药","caution":"脾胃虚寒者忌用。   ","classic":"1.热毒疮痈，痔疮，咽喉肿痛 本品苦寒，清热解毒之效颇佳，又能消散痈肿，故常用于热毒蕴结所致之疮疡痈疽、痔疮肿痛、咽喉肿痛等。治疗热毒疮痈，可用水调化或加入少许冰片，涂于患部；或配牛黄、芦荟、麝香等制成软膏外用。治疗久痔不愈，可用水调化后涂于患部，如《千金方》外涂熊胆粉；治热毒咽喉肿痛，常与牛黄、冰片、珍珠等同用，多作丸剂，内服或含化。   2.热极生风，惊痫抽搐 本品苦寒清热，有较好的凉心清肝、息风止痉功效。主治肝火炽盛，热极生风所致的高热惊风、癫痫、子痫，手足抽搐。如治疗小儿痰热惊痫，《食疗本草》单用本品和乳汁及竹沥化服；治子痫，可单用本品温开水化服，也可配伍钩藤、羚羊角、牛黄等清热息风止痉药。   3.肝热目赤，目生翳膜 本品主入肝经，又善于清肝明目退翳，故可用治肝热目赤肿痛，羞明流泪，目生翳膜等证，常配伍石决明、车前子等药；或以本品与冰片化水，外用点眼。治新生儿胎热目闭多眵，以本品少许，蒸水外洗。   ","dosage":"5g","effect":"清热解毒，息风止痉，清肝明目。   ","name":"熊胆粉","nature":"苦，寒。归肝、胆、心经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"内服，0.25～0.5g，入丸、散剂。外用适量，研末或水调涂敷患处。   "},{"cat":"清热解毒药","caution":"","classic":"附药：猪胆粉  本品为猪科动物猪Sus scrofadomestica Brisson.胆汁的干燥品。性味苦，寒；归肝、胆、肺、大肠经。功能清热润燥，止咳平喘，解毒。适用于顿咳，哮喘，热病燥渴，目赤，喉痹，黄疸，泄泻，痢疾，便秘，痈疮肿毒。内服：0.3～0.6g，冲服或入丸散。外用适量，研末或水调涂敷患处。","dosage":"","effect":"清热润燥，止咳平喘，解毒","name":"猪胆粉","nature":"苦，寒；归肝、胆、肺、大肠经","parent":"熊胆粉","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""},{"cat":"清热解毒药","caution":"脾胃虚寒者慎服。   ","classic":"1.痈肿疮毒 本品苦寒，具有较强的清热解毒、消散痈肿作用。用于热毒壅聚之痈肿疮毒，可单用鲜品，水煎内服并外洗，再将其捣烂外敷患处，或与金银花、野菊花、蒲公英等同用；本品清热解毒，又可用治水火烫伤及褥疮、下肢溃疡等症，如《江西草药》用治烫火伤，以千里光8份、白及2份。水煎浓汁外搽。   2.感冒发热 本品苦寒，取其清热解毒之功，可用于风热感冒，发热、咽痛等症，可单用煎服，或与金银花、连翘等配伍。   3.目赤肿痛 本品苦寒入肝，能清肝明目，治疗风热或肝火上炎所致的目赤肿痛，《江西民间草药》单用本品煎汤熏洗眼部，或与菊花、夏枯草、桑叶等药配伍。   4.湿热泻痢 本品味苦性寒，具有清利湿热之功。用于大肠湿热，腹痛泄泻，或下痢脓血，里急后重，可单用本品煎服；也可与银花炭、黄连、木香等同用。   5.皮肤湿疹 本品苦寒，能清热除湿以止痒，用治湿热所致之湿疹湿疮、阴囊湿痒，可煎汁浓缩成膏，涂搽患处。   ","dosage":"15～30g","effect":"清热解毒，清肝明目，利湿。   ","name":"千里光","nature":"苦，寒。归肺、肝经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～30g。外用适量，煎水熏洗。   "},{"cat":"清热解毒药","caution":"不宜与川乌、制川乌、草乌、制草乌、附子同用。   ","classic":"1.痈疽发背，疔疮，瘰疬 本品苦寒清泄，辛散消肿，故有清热解毒、消痈散结、敛疮生肌、消肿止痛之效。内服、外用皆可。用治热毒壅聚，痈疮初起，红肿硬痛者，可单用为末水调涂敷患处，或与金银花、连翘、蒲公英等同煎内服，以消肿散结；若疮痈脓成不溃者，亦可与苦参、天南星、皂角等制作膏药外贴，促使其溃破排脓；若疮疡溃后不敛，可与白及、乳香、没药等共研细末，干撒疮口，以生肌敛疮。若用治痰火郁结，痰核瘰疬，可与玄参、黄连、大黄等研末醋调，外敷患处。   2.烧烫伤，手足皲裂 本品苦寒，既能清解火热毒邪，又具敛疮生肌止痛之功。用治烧烫伤，《备急方》单用本品研末外敷；亦可与地榆等份为末外用。若与白及、大黄、冰片配伍麻油调敷，还可用于手足皲裂。   ","dosage":"5～10g","effect":"清热解毒，消痈散结，敛疮生肌。   ","name":"白蔹","nature":"苦，微寒。归心、胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～10g。外用适量，煎汤洗或研成极细粉敷患处。   "},{"cat":"清热解毒药","caution":"","classic":"1.烧烫伤，皮肤溃疡 本品苦涩性寒，外用有清热解毒、凉血、敛疮之功。尤长于治疗烧烫伤。外治烧烫伤，皮肤溃疡，可单用制成搽剂外涂患处；亦可用本品干叶研粉，麻油调敷，或用鲜叶捣烂，外敷患处。   2.肺热咳嗽，咽喉肿痛，痢疾，热淋，胁痛 本品苦寒，善于清热解毒，消肿祛瘀。用于肺热咳嗽，咽喉肿痛，风热感冒，或湿热所致小便淋沥涩痛，泄泻痢疾者，单用或分别配伍清肺泻火解毒药、清热利尿通淋药、清热止痢药。若瘀阻胁痛，可与郁金、川芎等活血化瘀药配伍。   3.外伤出血 本品有收敛止血之效。用于外伤出血，可单用鲜叶捣敷伤口；也可用干叶研细，撒敷伤口，外加包扎。   ","dosage":"15～60g","effect":"清热解毒，消肿祛瘀，凉血止血，敛疮。   ","name":"四季青","nature":"苦、涩，凉。归肺、大肠、膀胱经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～60g。外用适量，水煎外涂。   "},{"cat":"清热解毒药","caution":"脾胃虚寒，肠滑泄泻者不宜使用。   ","classic":"1.痈肿疮毒 本品甘寒，清热解毒，以消痈肿。可用于热毒疮痈肿痛，单用煎汁顿服，或生研加冷开水浸泡滤汁服；或与大黄为末加薄荷汁、蜂蜜调敷患处以解毒消肿。若与赤小豆、黑豆、甘草同用，又可预防痘疮及麻疹。   2.药食中毒 本品甘寒，善解热毒，为附子、巴豆、砒霜等辛热毒烈之剂中毒及食物中毒等的解毒良药。可用生品研末加冷开水滤汁顿服，或浓煎频服，或配伍黄连、葛根、甘草等药。   3.暑热烦渴 本品甘寒，能清热消暑，除烦止渴，通利小便，民间常作为清热消暑、解毒之食品。治暑热烦渴尿赤，夏季常用本品煮汤冷饮；亦可与西瓜翠衣、荷叶、青蒿等同用，以增强疗效。   4.水肿，小便不利 本品有一定的利水消肿之功，可用于治疗小便不通，淋沥不畅，水肿等，《圣惠方》以本品与陈皮、冬麻子同用煮食；或配伍茯苓、泽泻等利水消肿药，以增强疗效。   ","dosage":"15～30g","effect":"清热解毒，消暑，利水。   ","name":"绿豆","nature":"甘，寒。归心，胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～30g。外用适量。   "},{"cat":"清热解毒药","caution":"","classic":"本品为豆科植物绿豆Phaseolus radiatus L.的种皮。将绿豆用清水浸泡后取皮晒干即成。性味甘，寒；归心、胃经。功同绿豆，但解暑之力不及绿豆，其清热解毒之功胜于绿豆；并能退目翳，治疗斑痘目翳。煎服，6～12g。  ","dosage":"6～12g","effect":"","name":"绿豆衣","nature":"甘，寒；归心、胃经","parent":"绿豆","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，6～12g"},{"cat":"清热解毒药","caution":"","classic":"本品为豆科植物赤小豆Vigna umbeuata Ohwi et Ohashi或赤豆Vigna angularis Ohwi et Ohashi的干燥成熟种子。全国各地均产。秋季果实成熟而未开裂时拔起全株，晒干，打下种子，除去杂质，再晒干，生用。性味甘、酸，平；归心、小肠经。功能解毒排脓，利水消肿。适用于痈肿疮毒，肠痈腹痛，水肿胀满，脚气浮肿，黄疸尿赤，风湿热痹。煎服，9～30g。外用适量，研末调敷。  ","dosage":"9～30g","effect":"解毒排脓，利水消肿","name":"赤小豆","nature":"甘、酸，平；归心、小肠经","parent":"绿豆","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～30g"},{"cat":"清热解毒药","caution":"","classic":"本品为豆科草本植物大豆Glycine max （L.）Merr.的干燥成熟种子。全国各地均产。秋季采收成熟果实，晒干，打下种子，除去杂质。性味甘，平；归脾、肾经。功能益精明目，养血祛风，利水，解毒。适用于阴虚烦渴，头晕目昏，体虚多汗，肾虚腰痛，水肿尿少，痹痛拘挛，手足麻木，药食中毒。煎服，9～30g。外用适量，煎汤洗患处。","dosage":"9～30g","effect":"益精明目，养血祛风，利水，解毒","name":"黑豆","nature":"甘，平；归脾、肾经","parent":"绿豆","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～30g"},{"cat":"清热凉血药","caution":"","classic":"附药：鲜地黄  本品为玄参科植物地黄Rehmannia glutinosa Libosch.的新鲜块根。性味甘、苦，寒；归心、肝、肾经。功能清热生津，凉血，止血。适用于热病伤阴，舌绛烦渴，温毒发斑，吐血衄血，咽喉肿痛。煎服，12～30g。","dosage":"12～30g","effect":"清热生津，凉血，止血","name":"鲜地黄","nature":"甘、苦，寒；归心、肝、肾经","parent":"生地黄","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，12～30g"},{"cat":"清热凉血药","caution":"","classic":"附药：紫草茸  本品为紫胶虫科昆虫紫胶虫Laccifer Lacca kerr.在树枝上所分泌的胶质物。主产于云南、四川、台湾等地。7～8月间采收，置干燥、阴凉通风处直至干燥。性味苦，寒。功能清热，凉血，解毒。主治麻疹、斑疹透发不畅，疮疡肿毒，湿疹。本品作用与紫草相似，但无滑肠通便之弊。煎服，1.5～6g，或研末服。外用适量，研末撒。","dosage":"5～6g","effect":"清热，凉血，解毒","name":"紫草茸","nature":"苦，寒","parent":"紫草","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，1.5～6g，或研末服"},{"cat":"清热凉血药","caution":"脾胃虚寒者忌用。   ","classic":"1.温病高热，神昏谵语，惊风，癫狂 本品苦寒，入心肝血分，既能清热凉血、泻火解毒，又能定惊。治温热病热入营血，高热神昏谵语，惊风抽搐，可配伍石膏、玄参、羚羊角等药，如紫雪丹（《外台秘要》）。若配伍牛黄、珍珠母、黄芩等药，可治热病神昏，或中风偏瘫，神志不清，如清开灵口服液（《中华人民共和国药典·一部》2015年版）；若治癫狂，可配伍石菖蒲、郁金、玄参等药。   2.血热毒盛，发斑发疹，吐血衄血 取本品清热凉血之功，用治血热毒盛，发斑发疹，吐血衄血，常配伍生地黄、牡丹皮、赤芍等药。   3.痈肿疮疡，咽喉肿痛 取本品清热解毒之功，用治热毒疮痈，咽喉肿痛，可配伍黄连、黄芩、连翘等药。   ","dosage":"15～30g","effect":"清热凉血，解毒，定惊。   ","name":"水牛角","nature":"苦，寒。归心、肝经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～30g，宜先煎3小时以上。水牛角浓缩粉冲服，每次1.5～3g，每日2次。   "},{"cat":"清虚热药","caution":"本品苦寒，脾胃虚寒、食少便溏者不宜服用。   ","classic":"1.阴虚发热，骨蒸劳热，产后血虚发热，温邪伤营发热 本品苦咸性寒，善入血分，有退虚热、凉血清热之功。治疗阴虚发热，骨蒸潮热，常配伍生地黄、知母、地骨皮等滋阴清虚热之品。治疗产后血虚发热，低热不退，常与当归、人参等补益气血之品同用。治疗温热病后期，余热未尽，耗伤阴液，见夜热早凉者，常与生地、玄参、青蒿等同用。   2.热淋，血淋 本品既能清热凉血，又能利尿通淋。治疗热淋，血淋，常与滑石、车前子、木通等利尿通淋之品配伍。   3.痈疽肿毒，蛇虫咬伤，咽喉肿痛 本品有清热解毒，消肿疗疮之功，内服或外用均可。治疗热毒疮痈，可单用捣烂外敷；或配伍金银花、蒲公英等清热解毒药内服。治疗热毒壅盛咽喉肿痛，常与山豆根、射干、连翘等清热解毒利咽之品同用。   4.阴虚外感 本品能清泄肺热而透邪，清退虚热而护阴，治疗阴虚外感，发热咽干，口渴心烦，常与玉竹、薄荷、淡豆豉等配伍，如加减葳蕤汤（《通俗伤寒论》）。   ","dosage":"5～10g","effect":"清热凉血，利尿通淋，解毒疗疮。   ","name":"白薇","nature":"苦、咸，寒。归胃、肝、肾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～10g。外用适量。   "},{"cat":"峻下逐水药","caution":"","classic":"附药：红大戟  本品为茜草科植物红大戟knoxia vaierianoides Thotel et Pitard的根。又名红芽大戟、广大戟。性味苦、寒，有小毒；归肺、脾、肾经。功能泻水逐饮，消肿散结。适用于水肿胀满，胸腹积水，痰饮积聚，气逆喘咳，二便不利，痈肿疮毒，瘰疬痰核。煎服，1.5～3g；入丸散服，每次1g；内服醋炙用，以减低毒性。外用适量，生用。孕妇及虚弱者禁用；不宜与甘草同用。","dosage":"5～3g","effect":"泻水逐饮，消肿散结","name":"红大戟","nature":"苦、寒，有小毒；归肺、脾、肾经","parent":"京大戟","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，1.5～3g；入丸散服，每次1g；内服醋炙用，以减低毒性"},{"cat":"峻下逐水药","caution":"","classic":"附药：狼毒  本品为瑞香科植物瑞香狼毒Stellera chamaejasme I.的根。主产于东北、西北、河北等地。性味苦、辛，平，有毒；归肺、脾、肝经。功能泻水逐饮，破积杀虫。适用于水肿腹胀，痰食虫积，心腹疼痛，癥瘕积聚，结核，疥癣。煎服，1～3g；或入丸、散。外用适量，研末调敷，或醋磨汁涂，或取鲜根去皮捣烂敷。本品有毒，内服宜慎，过量服用可引起中毒。体质虚弱及孕妇禁用。不宜与密陀僧同用。","dosage":"1～3g","effect":"泻水逐饮，破积杀虫","name":"狼毒","nature":"苦、辛，平，有毒；归肺、脾、肝经","parent":"芫花","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，1～3g；或入丸、散"},{"cat":"峻下逐水药","caution":"","classic":"附药：巴豆  本品为大戟科植物巴豆Croton tiglium L.的干燥成熟果实。秋季果实成熟时采收，堆置2～3天，摊开，干燥。去皮，取净仁用。性味辛、热，有大毒；归胃、大肠经。外用蚀疮。适用于恶疮疥癣，疣痣。外用适量，研末涂患处，或捣烂以纱布包擦患处。孕妇及虚弱者禁用；不宜与牵牛子同用。本品专供外用，不作内服。","dosage":"","effect":"","name":"巴豆","nature":"辛、热，有大毒；归胃、大肠经","parent":"巴豆霜","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""},{"cat":"峻下逐水药","caution":"孕妇及虚弱者禁用。   ","classic":"1.二便不通，水肿，痰饮，积滞胀满 本品其性峻猛，能泻下逐水消肿，宜用于二便不通，水肿，痰饮，积滞胀满之实证。单用有效，或配大黄，酒水为丸服，或与防己、槟榔、葶苈子等药同用，以增强逐水消肿之功。   2.血瘀经闭，癥瘕 本品有破瘀血、消癥瘕、通经脉的作用。治瘀滞经闭者，可与当归、川芎、红花等同用。治癥瘕痞块，可与三棱、莪术、大黄等同用。   3.顽癣，赘疣 本品外用可疗癣蚀疣。治顽癣、恶疮肿毒及毒蛇咬伤等，可内服、外用。   ","dosage":"1～2g","effect":"泻下逐水，破血消癥；外用疗癣蚀疣。   ","name":"千金子","nature":"辛，温；有毒。归肝、肾、大肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"生千金子，1～2g，去壳，去油用，多入丸散服；外用适量，捣烂敷患处。千金子霜0.5～1g，多入丸散服；外用适量。   "},{"cat":"祛风寒湿药","caution":"","classic":"附药：草乌  本品为毛茛科植物北乌头Aconitum kusnezoffii Reichb.的干燥根。主产于东北、华北。秋季茎叶枯萎时采挖，除去须根及泥沙，干燥。生用或制后用。本品的药性、功效、应用、用法用量、使用注意与川乌相同，而毒性更强。","dosage":"","effect":"","name":"草乌","nature":"","parent":"川乌","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"用量、使用注意与川乌相同，而毒性更强"},{"cat":"祛风寒湿药","caution":"","classic":"附药：金钱白花蛇  本品为眼镜蛇科动物银环蛇Bungarus multicinctus Blyth的幼蛇干燥体。分布于长江以南各地。夏、秋二季捕捉，剖开蛇腹，除去内脏，擦净血迹，用乙醇浸泡处理后，盘成圆形，用竹签固定，干燥。切段用。本品药性、功效、应用、使用注意与蕲蛇相似而力较强。煎服，2～5g；研粉吞服，1～1.5g。亦可浸酒服。","dosage":"2～5g","effect":"","name":"金钱白花蛇","nature":"","parent":"蕲蛇","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，2～5g；研粉吞服，1～1.5g"},{"cat":"祛风寒湿药","caution":"","classic":"附药：蛇蜕  本品为游蛇科动物黑眉锦蛇Elaphe taeniura Cope、锦蛇Elaphe carinata （Guenther），或乌梢蛇Zaocys dhumnades （Cantor）等蜕下的干燥表皮膜。春末夏初或冬初收集，除去泥沙，干燥。性味咸、甘，平。归肝经。功能祛风，定惊，退翳，解毒。适用于小儿惊风，抽搐痉挛，翳障，喉痹，疔肿，皮肤瘙痒。煎服，2～3g；研末吞服，每次0.3～0.6g。外用适量。","dosage":"2～3g","effect":"祛风，定惊，退翳，解毒","name":"蛇蜕","nature":"咸、甘，平","parent":"乌梢蛇","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，2～3g；研末吞服，每次0.3～0.6g"},{"cat":"祛风寒湿药","caution":"","classic":"1.风湿痹证 本品辛甘发散，可以祛风，温燥而通，又善除湿舒筋，作用缓和，可用于各种痹证。《千金方》单用蒸热，温熨患处，以治风湿痹痛，肢体不遂者；若与羌活、独活、威灵仙等同用，可治风湿寒痹；与防己、薏苡仁、栀子等配伍，可治风湿热痹，肢节烦疼，如宣痹汤（《温病条辨》）。   2.吐泻转筋 本品入脾胃，能和胃化湿，湿去则泄泻可止、筋脉可舒。治暑湿中阻而致的腹痛吐泻转筋，常配木瓜、吴茱萸、薏苡仁等，如蚕矢汤（《霍乱论》）。   3.风疹、湿疹瘙痒 本品善于祛风湿，止痒，治疗风疹、湿疹，可单用煎汤外洗，或与白鲜皮、地肤子、蝉蜕等同用。   ","dosage":"5～15g","effect":"祛风除湿，和胃化湿。   ","name":"蚕沙","nature":"甘、辛，温。归肝、脾、胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～15g；宜布包入煎。外用适量。   "},{"cat":"祛风寒湿药","caution":"阴虚血燥者慎服。   ","classic":"1.风寒湿痹，历节风痛，转筋挛急 本品辛散苦燥温通，能祛风湿，通经络而止痛，入肝肾而善祛筋骨间风湿，性偏温燥，尤宜于寒湿偏盛之风湿痹证。治风湿痹痛，历节风痛，转筋挛急，《圣惠方》单用酿酒服；或与羌活、独活、川芎等活血通络药同用。   2.跌打伤痛 本品能通络止痛，治跌打损伤，瘀肿疼痛，《圣惠方》以之与醋同炒为末服；亦常配伍乳香、没药、红花等活血止痛药；若皮肤未破者，可酒浸擦患处。   ","dosage":"9～15g","effect":"祛风除湿，通络止痛。   ","name":"油松节","nature":"苦、辛，温。归肝、肾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～15g。外用适量。   "},{"cat":"祛风寒湿药","caution":"","classic":"附药：松花粉  本品为松科植物马尾松Pinus massoniana Lamb.、油松Pinus tabuliformis Carr.或同属数种植物的干燥花粉。性味甘，温；归肝、脾经。功能收敛止血，燥湿敛疮。适用于外伤出血，湿疹，黄水疮，皮肤糜烂，脓水淋漓。外用适量，撒敷患处。","dosage":"","effect":"收敛止血，燥湿敛疮","name":"松花粉","nature":"甘，温；归肝、脾经","parent":"油松节","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""},{"cat":"祛风寒湿药","caution":"本品有强烈的发汗作用，虚弱者慎用。孕妇禁用。   ","classic":"1.风湿痹痛，半身不遂 本品辛散温通，善于祛风除湿，消肿止痛。治风寒湿痹，半身不遂，手足麻木，腰腿酸痛，可单用酒水各半煎服，或与桂枝、羌活、乳香等配伍。   2.跌扑肿痛 本品有良好的消肿止痛之功，以本品为主配伍制成的冯了性风湿跌打药酒、丁公藤风湿药酒，亦常用于跌打损伤，瘀肿疼痛。   ","dosage":"3～6g","effect":"祛风除湿，消肿止痛。   ","name":"丁公藤","nature":"辛，温；有小毒。归肝、脾、胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"3～6g，用于配制酒剂，内服或外搽。   "},{"cat":"祛风寒湿药","caution":"体弱者不宜使用。孕妇禁用。小儿及育龄期妇女慎服。不宜过量或久服。   ","classic":"1.风湿痹证 本品辛散苦燥温通，善于祛风湿，通经络而止痛，为治风寒湿痹日久，关节肿痛麻木之良药。单用酒浸、煎服或与鸡血藤等配伍。《滇南本草》用本品与当归、川牛膝、木瓜等配伍酒浸，治筋骨疼痛，瘫痪痿软。   2.跌打损伤，骨折 本品辛能行散，善于活血通络，消肿止痛，续筋接骨，治跌打损伤，骨折肿痛，可单用外敷，亦可与天南星、半夏、川芎等配伍，如紫金皮散（《证治准绳》）。   ","dosage":"6～15g","effect":"祛风除湿，活血止痛，续筋接骨。   ","name":"昆明山海棠","nature":"苦、辛，微温；有大毒。归肝、脾、肾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，6～15g，宜先煎；或酒浸服。外用适量，研末敷，或煎水涂，或鲜品捣敷。   "},{"cat":"祛风湿热药","caution":"","classic":"1.风湿痹证 本品辛散苦燥，能祛风湿，通经络。治风湿痹痛，四肢麻木，可单用，或与豨莶草配伍，如豨桐丸（《济世养生经验集》）。   2.中风半身不遂 本品味辛能散能行，功能祛风通络，用治中风口眼㖞 斜，半身不遂，可与蕲蛇、当归、地龙等同用。   3.风疹，湿疮 本品辛能散风，苦燥除湿，治风疹、湿疮等皮肤瘙痒，可单用煎洗或外敷，也可与防风、苦参、地肤子等药配伍。   4.肝阳上亢，头痛眩晕 本品性凉入肝，能凉肝平肝，治肝阳上亢，头痛眩晕者，可单用，或与豨莶草同用，或与钩藤、菊花、夏枯草等配伍。现常用于高血压病。   ","dosage":"5～15g","effect":"祛风湿，通经络，平肝。   ","name":"臭梧桐","nature":"辛、苦、甘，凉。归肝经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～15g；用于高血压病不宜久煎。研末服，每次3g。外用适量。   "},{"cat":"祛风湿热药","caution":"","classic":"1.风湿痹证 本品辛能散风，苦能燥湿，主入肝经，能祛风湿，行经络，止疼痛，达病所，尤善治下肢关节痹痛。治风湿痹证，四肢拘挛，腰膝酸痛，或麻木不仁，常与薏苡仁、牛膝、五加皮等同用。   2.疥癣，湿疹 本品辛散苦燥，既能祛风燥湿，又能杀虫止痒，故可治疥癣、湿疹瘙痒，可单用或配蛇床子、苦参、土茯苓等煎汤外洗或内服。   ","dosage":"5～15g","effect":"祛风湿，通络止痛，杀虫止痒。   ","name":"海桐皮","nature":"苦、辛，平。归肝经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～15g；或酒浸服。外用适量。   "},{"cat":"祛风湿热药","caution":"","classic":"1.风湿热痹，筋脉拘挛，腰膝酸痛 本品善于祛风通络，苦能燥湿，微寒清热，尤宜于风湿热痹，筋脉拘挛，腰膝酸痛者，每与忍冬藤、秦艽、地龙等配伍；亦可单用酒浸服。   2.喉痹，痈肿 本品入心肝血分，味苦性微寒，能清热凉血，利咽消肿，故可用于热毒壅盛之喉痹、痈肿。《近效方》以之单用水煎，慢慢含咽，治热毒之咽喉肿痛。若与皂角刺、乳香、没药等配伍，可治痈肿疮毒。   3.跌扑损伤 本品能通经络，凉血而消肿止痛。治跌扑损伤，瘀滞肿痛，可与伸筋草、透骨草、红花等同用。   ","dosage":"6～12g","effect":"祛风通络，凉血消肿。   ","name":"络石藤","nature":"苦，微寒。归心、肝、肾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，6～12g。   "},{"cat":"祛风湿热药","caution":"","classic":"1.风湿痹痛，麻木拘挛，筋骨酸痛 本品辛能行散，苦能燥湿，性善疏通，有较好的祛风湿，通经络作用。治风湿痹痛，麻木拘挛，筋骨酸痛，可单用煎服或熬膏；或配威灵仙、独活、红花等祛风通络活血之品。   2.泄泻痢疾 本品能清热解毒而止泻痢，治湿热、热毒所致泄泻、痢疾，可单用或与黄连、马齿苋等配伍。   3.疮疡 本品有清热解毒之功，治疮疡内服外用皆可。内服可与蒲公英、金银花、紫花地丁等同用；外敷可制成软膏，以治湿毒蕴结之痈疔疮疖、湿疹、烧烫伤等。   ","dosage":"9～15g","effect":"祛风湿，通经络，止泻痢，清热解毒。   ","name":"老鹳草","nature":"辛、苦，平。归肝、肾、脾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～15g；或熬膏、酒浸服。外用适量。   "},{"cat":"祛风湿强筋骨药","caution":"","classic":"附药：天山雪莲  本品系维吾尔族习用药材，为菊科植物天山雪莲Saussurea involucrata （Kar.et Kir.）Sch.-Bip 的干燥地上部分。主产于新疆。夏、秋二季开花时采收，阴干。维吾尔医的性味：性质，二级湿热；中医的性味：微苦，温。维吾尔医的功能主治：补肾活血，强筋骨，营养神经，调节异常体液，用于风湿性关节炎，关节疼痛，肺寒咳嗽，肾与小腹冷痛，白带过多等；中医的功能主治：温肾助阳，祛风胜湿，通经活血。用于风寒湿痹痛、类风湿性关节炎，小腹冷痛，月经不调。煎服，3～6g；或酒浸服。外用适量。孕妇忌用。","dosage":"3～6g","effect":"主治：补肾活血，强筋骨，营养神经，调节异常体液，用于风湿性关节炎，关节疼痛，肺寒咳嗽，肾与小腹冷痛，白带过多等；中医的功能主治：温肾助阳，祛风胜湿，通经活血","name":"天山雪莲","nature":"：性质，二级湿热；中医的性味：微苦，温","parent":"千年健","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g；或酒浸服"},{"cat":"","caution":"","classic":"1.湿浊中阻，脘腹痞闷 本品气味芳香，为芳香化湿浊要药。用治湿浊中阻所致的脘腹痞闷，少食作呕，神疲体倦等症，常与苍术、厚朴等同用，如不换金正气散（《和剂局方》）。   2.呕吐 本品既能芳香化湿浊，又能和中止呕，故以治湿浊中阻所致之呕吐最为捷要。常与半夏、丁香等同用。若偏湿热者，配黄连、竹茹等；偏寒湿者，配生姜、白豆蔻等药；妊娠呕吐，配砂仁、苏梗等；脾胃虚弱者，配党参、白术等。   3.暑湿表证，湿温初起，发热倦怠，胸闷不舒；寒湿闭暑，腹痛吐泻 本品既能芳香化湿浊，又可发表解暑。治疗暑湿表证，或湿温初起，湿热并重，发热倦怠，胸闷不舒，多与黄芩、滑石、茵陈等同用，如甘露消毒丹（《温热经纬》）。治暑月外感风寒，内伤生冷而致恶寒发热，头痛脘闷，腹痛吐泻的寒湿闭暑证，常配伍紫苏、厚朴、半夏等，如藿香正气散（《和剂局方》）。   ","dosage":"3～10g","effect":"芳香化湿，和中止呕，发表解暑。   ","name":"广藿香","nature":"辛，微温。归脾、胃、肺经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～10g。   "},{"cat":"","caution":"","classic":"附药：厚朴花  本品为木兰科植物厚朴Magnolia officinalis Rehd.et Wils.，或凹叶厚朴Magnolia officinalis Rehd.et Wils.var. biloba Rehd.et Wils.的干燥花蕾。性味苦，微温；归脾、胃经。功能芳香化湿，理气宽中。适用于脾胃湿阻气滞，胸脘痞闷胀满，纳谷不香。煎服，3～9g。","dosage":"3～9g","effect":"芳香化湿，理气宽中","name":"厚朴花","nature":"苦，微温；归脾、胃经","parent":"厚朴","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g"},{"cat":"","caution":"","classic":"附药：砂仁壳  本品为姜科植物阳春砂Amomum uillosum Lour.、绿壳砂Amomum uillosum Lour. var. xanthioides T.L.Wu et Senjen，或海南砂 Amomumlongiligulare T.L.Wu的果壳。性味功效与砂仁相似，而温性略减，药力薄弱，适用于脾胃湿阻气滞，脘腹胀痛，呕恶食少等症。煎服，3～6g。","dosage":"3～6g","effect":"","name":"砂仁壳","nature":"功效与砂仁相似，而温性略减，药力薄弱，适用于脾胃湿阻气滞，脘腹胀痛，呕恶食少等症","parent":"砂仁","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g"},{"cat":"","caution":"阴虚血燥者慎用。   ","classic":"1.湿浊中阻，脾胃气滞，不思饮食，胸腹胀痛，食积不消 本品既可化湿行气，又能开胃消食。治疗湿阻中焦，脘腹痞满，不思饮食，常与藿香、佩兰、陈皮等同用；若与黄芪、白术、人参等同用，可用于脾虚湿阻气滞之胸腹虚胀，食少无力者。治疗脾胃气滞，食积不消，胸腹胀痛，可与陈皮、枳实、木香等药配伍。   2.湿温初起，胸闷不饥 本品辛散入肺而宣化湿邪，故常用于湿温初起，胸闷不饥。若湿邪偏重者，每与薏苡仁、苦杏仁等同用，如三仁汤（《温病条辨》）；若热重于湿者，又常与黄芩、滑石等配伍，如黄芩滑石汤（《温病条辨》）。   3.寒湿呕逆 本品能行气宽中，温胃止呕，尤以胃寒湿阻气滞之呕吐最为适宜。可单用为末服，或配藿香、半夏等药。若与砂仁、甘草等药研细末服，用于小儿胃寒，吐乳不食者。   ","dosage":"3～6g","effect":"化湿行气，温中止呕，开胃消食。   ","name":"豆蔻","nature":"辛，温。归肺、脾、胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g，后下。   "},{"cat":"","caution":"","classic":"附药：豆蔻壳  本品为姜科草本植物白豆蔻Amomum kravanh Pierre ex Gagnep.或瓜哇白豆蔻Amomum compactum Soland ex Maton的果壳。性味功效与豆蔻相似，但温性不强，力亦较弱。适用于脾胃湿阻气滞所致的脘腹痞闷，食欲不振，呕吐等。煎服，3～6g。","dosage":"3～6g","effect":"","name":"豆蔻壳","nature":"功效与豆蔻相似，但温性不强，力亦较弱","parent":"豆蔻","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g"},{"cat":"","caution":"阴虚血燥者慎用。   ","classic":"1.寒湿内阻，脾胃气滞，脘腹胀满冷痛，不思饮食 本品芳香温燥，长于燥湿化浊，温中散寒，行气消胀，故脾胃寒湿偏胜，气机不畅者宜之。常与干姜、厚朴、陈皮等温中行气之品同用。   2.嗳气呕逆 本品可温中散寒，降逆止呕。治疗寒湿内盛，胃气上逆之呕吐呃逆，多与肉桂、高良姜、陈皮等药同用。  此外，取本品温燥之性，温脾燥湿，以除中焦之寒湿而止泻痢，用于寒湿内盛，清浊不分而腹痛泻痢者，可与苍术、厚朴、木香等同用。   ","dosage":"3～6g","effect":"燥湿行气，温中止呕。   ","name":"草豆蔻","nature":"辛，温。归脾、胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g。   "},{"cat":"利水消肿药","caution":"","classic":"本品为多孔菌科真菌茯苓Poria cocos （Schw.） Wolf菌核的干燥外皮。性味甘、淡、平；归心、肺、脾、肾经。功能利水消肿。适用于水肿，小便不利。煎服15～30g。  ","dosage":"15～30g","effect":"利水消肿","name":"茯苓皮","nature":"甘、淡、平；归心、肺、脾、肾经","parent":"茯苓","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服15～30g"},{"cat":"利水消肿药","caution":"","classic":"本品为多孔菌科真菌茯苓Poria cocos （Schw.） Wolf干燥菌核中间带有松根的部分。性味甘、淡、平；归心、肺、脾、肾经。功能宁心安神。适用于心神不安，惊悸，健忘，失眠。煎服10～15g。","dosage":"10～15g","effect":"宁心安神","name":"茯神","nature":"甘、淡、平；归心、肺、脾、肾经","parent":"茯苓","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服10～15g"},{"cat":"利水消肿药","caution":"","classic":"1.水肿胀满，小便不利 本品味甘，药性平和，善于利水消肿。用治水肿，小便不利，常与五加皮、生姜皮等配伍；若治体虚浮肿，常与冬瓜皮、赤小豆、红糖等同用。   2.暑热口渴，小便短赤 本品性凉，有清热解暑之功。用治夏日暑热口渴，小便短赤，常配冬瓜皮、西瓜皮等药，煎水代茶饮；若治暑湿证，可与薏苡仁、滑石、扁豆花等同用。   ","dosage":"9～30g","effect":"利尿消肿，清热解暑。   ","name":"冬瓜皮","nature":"甘，凉。归脾、小肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～30g。   "},{"cat":"利水消肿药","caution":"","classic":"附药：冬瓜子  本品为葫芦科植物冬瓜Benincasa hispida （Thunb.） Cogn.的干燥成熟种子。性味甘，微寒；归肺、脾、小肠经。功能清热化痰，排脓，利湿。适用于痰热咳嗽，肺痈，肠痈，带下，白浊。煎服，10～15g。","dosage":"10～15g","effect":"清热化痰，排脓，利湿","name":"冬瓜子","nature":"甘，微寒；归肺、脾、小肠经","parent":"冬瓜皮","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，10～15g"},{"cat":"利水消肿药","caution":"","classic":"1.水肿 本品甘淡渗泄，功能利水渗湿以消肿。治疗水肿，小便不利，可单用玉米须大剂量煎服，或与泽泻、冬瓜皮、赤小豆等药同用；亦可治脾虚水肿，常与白术、茯苓等配伍；本品归膀胱经，利水而通淋，尤宜于膀胱湿热之小便短赤涩痛，可单味大量煎服，亦可与车前草、珍珠草等同用；用于石淋，可以本品单味煎浓汤顿服，也可与海金沙、金钱草等同用。   2.黄疸 本品能利湿而退黄，药性平和，故阳黄、阴黄均可配伍使用。治疗湿热阳黄，可单味大剂量煎汤服，亦可与金钱草、郁金、茵陈等配伍；若寒湿黄疸，可与附子、干姜、茵陈蒿等药同用。   ","dosage":"15～30g","effect":"利水消肿，利湿退黄。   ","name":"玉米须","nature":"甘，平。归膀胱、肝、胆经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～30g。鲜品加倍。   "},{"cat":"利水消肿药","caution":"","classic":"1.水肿胀满 本品味淡气薄，功专利水消肿。用于面目浮肿，大腹水肿，小便不利证，可与猪苓、茯苓、泽泻等药同用。   2.淋证 本品利水而通淋。用于热淋，配伍滑石、木通、车前子等；用于血淋，配萹蓄、白茅根、小蓟等。  此外，葫芦还可利湿而退黄，用治湿热黄疸，可与茵陈蒿、栀子、金钱草等同用。   ","dosage":"15～30g","effect":"利水消肿。   ","name":"葫芦","nature":"甘，平。归肺、肾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～30g。   "},{"cat":"利水消肿药","caution":"本品有毒，不宜长期或过量服用。   ","classic":"1.下肢浮肿，心悸气短 本品入心、肾二经，有温助心肾，利水消肿作用，临床常用治下肢浮肿，心悸气短，可与葶苈子、黄芪等药同用。   2.风寒湿痹，腰膝酸软 本品辛散苦燥，具有祛风湿、强筋骨之功，为治风湿痹证常用药。用于风寒湿痹，腰膝酸软，常与当归、独活、淫羊藿等同用；若筋骨痿软行迟，则与怀牛膝、木瓜、巴戟天等同用。   ","dosage":"3～6g","effect":"利水消肿，祛风湿，强筋骨。   ","name":"香加皮","nature":"辛、苦，温；有毒。归肝、肾、心经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g。   "},{"cat":"利水消肿药","caution":"","classic":"1.水肿 本品能通利水道而消除水肿。用于水湿停蓄所致的水肿，小便不利，可与茯苓、猪苓、泽泻等同用。   2.醉酒 本品善解酒毒，清胸膈之热。治醉酒，烦热口渴，《世医得效方》将本品与麝香为末，面糊为丸，盐汤送服；用于饮酒过度，成痨吐血，可与白茅根、白及、甘蔗等配伍。   ","dosage":"10～15g","effect":"利水消肿，解酒毒。   ","name":"枳椇子","nature":"甘，平。归胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，10～15g。   "},{"cat":"利尿通淋药","caution":"","classic":"附药：车前草  本品为车前科植物车前Plantago asiatica L.或平车前Plantago depressa Willd.的干燥全草。性味甘，寒；归肝、肾、肺、小肠经。功能清热利尿通淋，祛痰，凉血，解毒。适用于热淋涩痛，水肿尿少，暑湿泄泻，痰热咳嗽，吐血衄血，痈肿疮毒。煎服9～30g。","dosage":"9～30g","effect":"清热利尿通淋，祛痰，凉血，解毒","name":"车前草","nature":"甘，寒；归肝、肾、肺、小肠经","parent":"车前子","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服9～30g"},{"cat":"利尿通淋药","caution":"","classic":"附药：川木通  本品为毛茛科植物小木通Clematis armandii Franch. 或绣球藤Clematis Montana Buch.-Ham.的干燥藤茎。性味苦，寒；归心、小肠、膀胱经。功能利尿通淋，清心除烦，通经下乳。适用于淋证，水肿，心烦尿赤，口舌生疮，经闭乳少，湿热痹痛。煎服，3～6g。孕妇慎用；不宜长期或大量服用。","dosage":"3～6g","effect":"利尿通淋，清心除烦，通经下乳","name":"川木通","nature":"苦，寒；归心、小肠、膀胱经","parent":"木通","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g"},{"cat":"利尿通淋药","caution":"","classic":"1.热淋涩痛，小便短赤 本品性微寒，主入膀胱经，能清利下焦湿热。多用于热淋涩痛，小便短赤，以及石淋，常与木通、瞿麦、车前子等同用，如八正散（《和剂局方》）；用于血淋，可与大蓟、小蓟、白茅根等同用。   2.虫积腹痛，皮肤湿疹，阴痒带下 本品苦能燥湿，微寒清热，又善“杀三虫”。用治蛔虫病，蛲虫病，钩虫病，煎汤空腹服，以提高疗效。治蛔虫腹痛，面青，《药性论》以本品单味浓煎服；治小儿蛲虫，下部痒，《食医心镜》单味水煎，空腹饮之，也可用本品煎汤，熏洗肛门；用于皮肤湿疹、湿疮、阴痒带下，可单味煎水外洗，亦可配伍地肤子、蛇床子、荆芥等煎水外洗。   ","dosage":"9～15g","effect":"利尿通淋，杀虫，止痒。   ","name":"萹蓄","nature":"苦，微寒。归膀胱经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～15g。外用适量，煎洗患处。   "},{"cat":"利尿通淋药","caution":"","classic":"热淋，石淋，血淋，膏淋，尿道涩痛 本品其性下降，善清小肠、膀胱湿热，尤善止尿道疼痛，为治诸淋涩痛之要药。治热淋涩痛，《泉州本草》以本品为末，甘草汤送服；治血淋，《普济方》以本品为末，新汲水或砂糖水送服；治石淋，与鸡内金、金钱草等配伍；治膏淋，可与萆薢、滑石、石菖蒲等同用。本品又能利水消肿，治疗水肿，多与泽泻、猪苓、防己等配伍，以加强利尿作用。   ","dosage":"6～15g","effect":"清热利湿，通淋止痛。   ","name":"海金沙","nature":"甘、咸，寒。归膀胱、小肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，6～15g，包煎。   "},{"cat":"利尿通淋药","caution":"","classic":"附药：海金沙藤  本品为海金沙科植物海金沙Lygodium japonicum （Thunb.） Sw.的干燥地上部分。性能功效与海金沙相似，兼能清热解毒。除治淋证涩痛外，亦用于痈肿疮毒、痄腮和黄疸。煎服，15～30g。外用适量，煎汤外洗或捣敷。","dosage":"15～30g","effect":"","name":"海金沙藤","nature":"","parent":"海金沙","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～30g"},{"cat":"利尿通淋药","caution":"本品寒润滑利，脾虚便溏及孕妇慎用。   ","classic":"1.淋证，水肿，尿闭 本品甘寒滑利，有利尿通淋之功。用于热淋，可与石韦、瞿麦、滑石等同用；用于血淋及妊娠子淋，《千金方》单用本品；用于石淋，可与海金沙、金钱草、鸡内金等同用。本品质滑，通关格，利小便，消水肿，用于水肿胀满，小便不利，配猪苓、泽泻、茯苓等同用；若治关格胀满，大小便不通，《肘后方》以本品单味为末服。   2.乳汁不通，乳房胀痛 本品滑润利窍，有通乳汁之功。用于产后乳汁不通，乳房胀痛，可与穿山甲、王不留行等同用。   3.肠燥便秘 本品质润滑利，润肠而通便。用于肠燥便秘，可与郁李仁、苦杏仁、桃仁等同用。   ","dosage":"3～9g","effect":"清热利尿，下乳，润肠。   ","name":"冬葵子","nature":"甘、涩，凉。归大肠、小肠、膀胱经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g。   "},{"cat":"利尿通淋药","caution":"","classic":"1.热淋，尿少涩痛 本品甘淡能渗湿，性寒能清热，故可清热利尿，适用于热淋，小便不利，尿少涩痛。因其质轻力薄，临证多与木通、瞿麦、车前子等同用，如八正散（《和剂局方》）。   2.心烦失眠，口舌生疮 本品性寒，既能入心清心火，又可利尿泄热以引异心火下降。用于心烦失眠，尿少涩痛，如《集验方》单味煎服，也可与木通、竹叶、栀子等同用；用于小儿心热夜啼，可与淡竹叶配伍，开水泡服，也可配车前草，煎汤服；治口舌生疮，咽喉肿痛，将灯心炭研为末，涂抹患处或蘸盐吹喉。   ","dosage":"1～3g","effect":"利小便，清心火。   ","name":"灯心草","nature":"甘、淡，微寒。归心、肺、小肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，1～3g。   "},{"cat":"利湿退黄药","caution":"","classic":"本品为唇形科植物活血丹G1echoma longituba （Nakai） Kupr.的干燥地上部分，药材也称江苏金钱草，为江苏、浙江所习用。性味辛、微苦，微寒；归肝、肾、膀胱经。功能利湿通淋，清热解毒，散瘀消肿。适用于热淋，石淋，湿热黄疸，疮痈肿痛，跌打损伤。煎服15～30g。外用适量，煎汤洗。  ","dosage":"15～30g","effect":"利湿通淋，清热解毒，散瘀消肿","name":"连钱草","nature":"辛、微苦，微寒；归肝、肾、膀胱经","parent":"金钱草","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服15～30g"},{"cat":"利湿退黄药","caution":"","classic":"本品为豆科植物广金钱草Desmodium styracifo1ium （Osb.） Merr. 的干燥地上部分，为广东、广西所习用。性味甘、淡，凉；归肝、肾、膀胱经。功能利湿退黄，利尿通淋。适用于黄疸尿赤，热淋，石淋，小便涩痛，水肿尿少。煎服15～30g。  ","dosage":"15～30g","effect":"利湿退黄，利尿通淋","name":"广金钱草","nature":"甘、淡，凉；归肝、肾、膀胱经","parent":"金钱草","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服15～30g"},{"cat":"利湿退黄药","caution":"","classic":"本品为伞形科植物白毛天胡荽Hydrocotyle sibthorpiodes Lam.var.batrachium （Hance） Hand. Mazz.的干燥地上部分，为江西所习用。性味甘、淡、微辛，凉；归肝、胆、肾经。功能清热利湿，解毒消肿。适用于湿热黄疸，痢疾，淋证，水肿。煎服10～15g。  ","dosage":"10～15g","effect":"清热利湿，解毒消肿","name":"江西金钱草","nature":"甘、淡、微辛，凉；归肝、胆、肾经","parent":"金钱草","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服10～15g"},{"cat":"利湿退黄药","caution":"","classic":"本品为旋花科植物马蹄金Dichondra repens Forst.的干燥地上部分，为四川部分地区所习用。性味苦、辛，凉；归肺、肝、胆经。功能清热利湿，利水消肿，活血解毒。适用于湿热黄疸，湿热下痢，热淋，水肿，小便不利，疔疮肿毒，跌打损伤。煎服10～30g。","dosage":"10～30g","effect":"清热利湿，利水消肿，活血解毒","name":"小金钱草","nature":"苦、辛，凉；归肺、肝、胆经","parent":"金钱草","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服10～30g"},{"cat":"利湿退黄药","caution":"","classic":"1.湿热黄疸 本品苦凉，入肝胆经，能清热解毒利湿而退黄疸，用治湿热黄疸。可单用大剂量煎汤服，或与金钱草、茵陈蒿、郁金等同用。   2.肺痈，肠痈，痈肿疮毒 本品能清热解毒而消痈肿。治肺痈，常与鱼腥草、薏苡仁、芦根等同用；治乳痈，常与蒲公英、穿山甲等配伍；治肠痈，可与败酱草、冬瓜仁、红藤等药同用；若湿热毒气所致痈肿疮毒，可单用地耳草捣烂外敷，或煎水内服。   3.跌打损伤 本品能活血消肿，用治跌打损伤瘀肿疼痛，单用或配骨碎补、乳香、没药等煎服，可同时用鲜品捣烂外敷。   ","dosage":"15～30g","effect":"利湿退黄，清热解毒，活血消肿。   ","name":"地耳草","nature":"苦，凉。归肝、胆经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～30g。外用适量。   "},{"cat":"利湿退黄药","caution":"","classic":"1.湿热黄疸，小便不利 本品能利湿退黄。用于湿热黄疸，小便不利，常与虎杖、茵陈等同用。   2.痈肿疮疡，咽痛，毒蛇咬伤，烧烫伤 本品有清热解毒及消痈散肿之功效。用于痈肿疮疡，可单用内服或外敷，或配伍野菊花、紫花地丁、半边莲等药；用于咽喉肿痛，常与山豆根同用；治疗毒蛇咬伤，常与白花蛇舌草、鱼腥草配伍。治疗烧烫伤，可鲜品捣汁外涂。   ","dosage":"15～30g","effect":"利湿退黄，清热解毒。   ","name":"垂盆草","nature":"甘、淡，凉。归肝、胆、小肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～30g。   "},{"cat":"利湿退黄药","caution":"","classic":"1.湿热黄疸 本品甘微苦凉，具有清热利湿而退黄之功，治疗肝胆湿热郁蒸引起的黄疸，可单味使用，或与茵陈、地耳草等药配伍。   2.乳痈肿痛 本品有清热解毒之功，治疗乳痈，常用本品鲜叶捣烂外敷。   3.胁肋不舒，胃脘胀痛 本品入肝胃二经，具疏肝止痛之功，治肝气郁结之胁肋不舒，胃脘疼痛，常与两面针同用。   ","dosage":"15～30g","effect":"利湿退黄，清热解毒，疏肝止痛。   ","name":"鸡骨草","nature":"甘、微苦，凉。归肝、胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～30g。   "},{"cat":"利湿退黄药","caution":"苦凉之品，阳虚体弱者慎用。   ","classic":"1.湿热黄疸，泄痢，淋证 本品苦甘性凉，苦以泄降，凉可清热，其入肝经，通利肝胆，去湿退黄，对于湿热蕴结肝胆，面目皮肤色黄如橘者，常与茵陈、栀子等同用。本品还可清热利湿通淋，用于膀胱湿热之热淋涩痛及砂淋、石淋，常与金钱草、海金砂等配伍；本品既利湿热，又解热毒，治湿热毒邪下注大肠所致的泄泻或便下脓血，里急后重，常配黄连、木香等。   2.疮疡肿毒，蛇犬咬伤 本品性凉，能清热解毒。用治热毒蕴结之疮痈肿毒，毒蛇咬伤或狂犬咬伤，可内服外敷并用，或与白花蛇舌草、重楼等同用。   3.目赤肿痛 本品入肝经，苦凉泄火，清热明目。可治肝热上攻，风热注目之赤眼红肿，涩痛难忍，单用或配菊花内服外洗。   4.小儿疳积 本品甘可健脾，凉以清热，治小儿禀赋素弱，过食肥甘，脾胃失运，食积化热所致的疳积，可单用水炖服，也可配伍使君子、芦荟等。   ","dosage":"15～30g","effect":"利湿退黄，清热解毒，明目，消积。   ","name":"珍珠草","nature":"甘、苦，凉。归肝、肺经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～30g。外用适量。   "},{"cat":"","caution":"","classic":"附药：八角茴香  本品为木兰科植物八角茴香Illicium verum Hook.F.的干燥成熟果实。又名大茴香、八角。主产于亚热带地区。生用或盐水炒用。性味辛温，归肝、肾、脾、胃经。功能温阳散寒，理气止痛。适用于寒疝腹痛，肾虚腰痛，胃寒呕吐，脘腹冷痛。煎服，3～6g。","dosage":"3～6g","effect":"温阳散寒，理气止痛","name":"八角茴香","nature":"辛温，归肝、肾、脾、胃经","parent":"小茴香","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g"},{"cat":"","caution":"","classic":"附药：母丁香  本品为桃金娘科植物丁香Eugenia caryophyllata Thunb.的干燥近成熟果实，又名鸡舌香。性味归经、功效主治、用法用量、使用注意与公丁香相似，但气味较淡，功力较逊。","dosage":"","effect":"","name":"母丁香","nature":"归经、功效主治、用法用量、使用注意与公丁香相似，但气味较淡，功力较逊","parent":"丁香","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"用量、使用注意与公丁香相似，但气味较淡，功力较逊"},{"cat":"","caution":"","classic":"附药：红豆蔻  本品为姜科植物大高良姜Alpinia galanga （L.） willd的干燥成熟果实。性味辛温，归脾、肺经，功能散寒燥湿，醒脾消食。适用于脘腹冷痛，食积腹胀，呕吐泄泻，饮酒过多。煎服，3～6g。","dosage":"3～6g","effect":"散寒燥湿，醒脾消食","name":"红豆蔻","nature":"辛温，归脾、肺经，功能散寒燥湿，醒脾消食","parent":"高良姜","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g"},{"cat":"","caution":"","classic":"附药：椒目  本品为芸香科植物青椒Zanthoxylum schinifolium Sieb.et Zucc.，或花椒Z. bungeanum Maxim.的种子。性味苦寒。归肺、肾、膀胱经。功能利水消肿，降气平喘。适用于水肿胀满、痰饮咳喘等。煎服，3～10g。","dosage":"3～10g","effect":"利水消肿，降气平喘","name":"椒目","nature":"苦寒","parent":"花椒","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～10g"},{"cat":"","caution":"","classic":"1.胃寒呕吐，腹痛泄泻，食欲不振 本品味辛性热，能温中散寒止痛，用治胃寒脘腹冷痛、呕吐，可单用研末入猪肚中炖服，或与高良姜、荜茇等同用；治反胃、不欲饮食，可与半夏、姜汁为丸服；治脾胃虚寒之泄泻，可与吴茱萸、白术等同用。   2.癫痫痰多 本品辛散温通，能下气行滞消痰，治痰气郁滞，蒙蔽清窍的癫痫痰多，常与荜茇等分为末服。  此外，胡椒作调味品，有开胃进食的作用。   ","dosage":"5g","effect":"温中散寒，下气，消痰。   ","name":"胡椒","nature":"辛，热。归胃、大肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"每次0.6～1.5g，研粉吞服。外用适量。   "},{"cat":"","caution":"","classic":"1.中寒脘腹冷痛，呕吐，泄泻 本品辛散温通，能温中散寒止痛，降胃气，止呕呃。用治胃寒脘腹冷痛、呕吐、呃逆、泄泻等，常与干姜、厚朴、附子等配伍；治脾胃虚寒之腹痛冷泻，可与白术、干姜、肉豆蔻等同用。   2.寒凝气滞，胸痹心痛，头痛，牙痛 本品辛散温通，功能散寒止痛。治疗寒凝气滞之胸痹心痛，常与檀香、延胡索、高良姜等同用；治疗感寒头痛，可与川芎、藁本等药配伍。以本品配胡椒研末，填塞龋齿孔中，可治龋齿疼痛。   ","dosage":"1～3g","effect":"温中散寒，下气止痛。   ","name":"荜茇","nature":"辛，热。归胃、大肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，1～3g。外用适量，研末塞龋齿孔中。   "},{"cat":"","caution":"","classic":"1.胃寒呕逆，脘腹冷痛 本品辛散温通，能温中散寒止痛。李时珍称其“暖脾胃，止呕吐哕逆。”治胃寒脘腹冷痛、呕吐、呃逆，功似荜茇，可单用或与高良姜、丁香、厚朴等同用。   2.寒疝腹痛 本品味辛性温，能散寒行气止痛。治疗寒疝腹痛，常与吴茱萸、香附、木香等同用。   3.寒湿郁滞，小便浑浊 本品辛温，能温里散寒。用治寒湿郁滞之小便浑浊，或下焦虚寒之小便不利，可与萆薢、茯苓、乌药等同用。   ","dosage":"1～3g","effect":"温中散寒，行气止痛。   ","name":"荜澄茄","nature":"辛，温。归脾、胃、肾、膀胱经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，1～3g。   "},{"cat":"","caution":"","classic":"为芸香科植物橘 Citrus reticulata Blanco 及其栽培变种的干燥外层果皮。性味辛、苦，温；归脾、肺经。功能理气宽中，燥湿化痰。适用于咳嗽痰多，食积伤酒，呕恶痞闷。煎服，3～10g。  ","dosage":"3～10g","effect":"理气宽中，燥湿化痰","name":"橘红","nature":"辛、苦，温；归脾、肺经","parent":"陈皮","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～10g"},{"cat":"","caution":"","classic":"为芸香科植物橘 Citrus reticulata Blanco 及其栽培变种的中果皮及内果皮之间的纤维束群。性味甘、苦，平。归肝、肺经。功能行气通络，化痰止咳。适用于痰滞经络之胸痛、咳嗽、痰多。煎服，3～5g。  ","dosage":"3～5g","effect":"行气通络，化痰止咳","name":"橘络","nature":"甘、苦，平","parent":"陈皮","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～5g"},{"cat":"","caution":"","classic":"为芸香科植物橘 Citrus reticulata Blanco 及其栽培变种的叶。性味辛、苦，平。归肝经。功能疏肝行气，散结消肿。适用于胁肋作痛、乳痈、乳房结块等。煎服，6～10g。  ","dosage":"6～10g","effect":"疏肝行气，散结消肿","name":"橘叶","nature":"辛、苦，平","parent":"陈皮","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，6～10g"},{"cat":"","caution":"","classic":"为芸香科植物化州柚 Citrus grandis ‘Tomentosa’或柚Citrus grandis （L.）Osbeck 的未成熟或接近成熟外层果皮。前者习称“毛橘红”，后者习称“光七爪”“光五爪”。性味辛、苦，温；归肺、脾经。功能理气宽中，燥湿化痰。适用于咳嗽痰多，食积伤酒，呕恶痞闷等。煎服，3～6g。","dosage":"3～6g","effect":"理气宽中，燥湿化痰","name":"化橘红","nature":"辛、苦，温；归肺、脾经","parent":"陈皮","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g"},{"cat":"","caution":"","classic":"本品为菊科植物川木香Vladimiria souliei （Frannch.）Ling或灰毛川木香Vladimiria souliei （Frannch.）Ling var.cinera Ling的干燥根。性味辛、苦，温；归脾、胃、大肠、胆经。功能行气止痛。用于胸胁、脘腹胀痛，肠鸣腹泻，里急后重。煎服，3～9g。  ","dosage":"3～9g","effect":"行气止痛","name":"川木香","nature":"辛、苦，温；归脾、胃、大肠、胆经","parent":"木香","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g"},{"cat":"","caution":"","classic":"本品为菊科植物土木香 Inula helenium L.的干燥根。性味辛、苦，温；归肝、脾经。功能健脾和胃，行气止痛，安胎。适用于胸胁、脘腹胀痛，呕吐泻痢，胸胁挫伤，岔气作痛，胎动不安。3～9g，多入丸散服。","dosage":"","effect":"健脾和胃，行气止痛，安胎","name":"土木香","nature":"辛、苦，温；归肝、脾经","parent":"木香","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""},{"cat":"","caution":"","classic":"1.肝胃气滞，胸胁胀痛 本品辛能行散，苦能疏泄，入肝经，能疏肝理气而止痛。治肝郁胸胁胀痛，可与柴胡、郁金、佛手等同用。   2.脾胃气滞，脘腹痞满，呕吐噫气 本品气香醒脾，辛行苦泄，入脾胃以行气宽中。用治脾胃气滞之脘腹胀痛，嗳气吞酸，呕恶食少，可与木香、砂仁、藿香等同用。   3.痰多咳嗽 本品苦燥降泄以化痰止咳，辛行入肺而理气宽胸。用治湿痰咳嗽、痰多胸闷等，可配伍生姜、半夏、茯苓等。   ","dosage":"3～10g","effect":"疏肝解郁，理气宽中，燥湿化痰。   ","name":"香橼","nature":"辛、苦、酸，温。归肝、脾、肺经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～10g。   "},{"cat":"","caution":"","classic":"1.肝胃气痛，食少呕恶 本品芳香行气，味苦疏泄，归肝、胃经，既能疏肝，又能宽中和胃。治疗肝胃不和之胸胁脘腹胀痛，呕恶食少，可与香附、佛手、砂仁等配伍。   2.月经不调，经前乳房胀痛 本品善于疏肝行气止痛，治肝郁气滞之月经不调，经前乳房胀痛，可与当归、川芎、白芍等配伍。   3.跌扑伤痛 本品味苦疏泄，性温通行，有活血止痛之功。治疗跌打损伤，瘀肿疼痛，可与当归、川芎、赤芍等配伍。   ","dosage":"3～6g","effect":"行气解郁，和血，止痛。   ","name":"玫瑰花","nature":"甘、微苦，温。归肝、脾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g。   "},{"cat":"","caution":"","classic":"1.肝胃气痛，郁闷心烦 本品芳香行气入肝胃，能疏肝解郁，理气和中。治疗肝胃气滞，胁肋胀痛，郁闷心烦，脘腹痞满，嗳气纳呆等症，可与柴胡、佛手、香附等配伍。   2.梅核气 本品芳香行气，化痰散结。治疗痰气郁结之梅核气，可与半夏、厚朴、茯苓等同用。   3.瘰疬疮毒 本品能化痰散结。治疗瘰疬痰核，疮疡肿毒，可与连翘、夏枯草、玄参等配伍。   ","dosage":"3～5g","effect":"疏肝和中，化痰散结。   ","name":"梅花","nature":"微酸，平。归肝、胃、肺经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～5g。   "},{"cat":"","caution":"","classic":"肝胃气滞，胸腹胀闷，胃脘疼痛 本品既能疏肝解郁以行滞，又能理气宽中以和胃。治疗肝郁气滞之胁肋胀痛或肝胃气滞之胸胁、脘腹胀痛，可与青皮、佛手、枳壳等配伍；治肝郁气滞、经前乳房胀痛，可与路路通、香附、郁金等同用。   ","dosage":"3～9g","effect":"疏肝理气，和胃止痛。   ","name":"娑罗子","nature":"甘，温。归肝、胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g。   "},{"cat":"","caution":"","classic":"1.寒郁气滞，脘腹胀满，食欲不振，呕吐 本品辛温芳香，专归脾胃经，故能行气消胀，醒脾开胃，散寒止痛。治寒湿阻滞、气机不畅之脘腹胀痛，食欲不振、恶心呕吐等，可与木香、砂仁、陈皮等同用；治思虑伤脾，胸闷腹胀，不思饮食，可与柴胡、郁金、豆蔻等同用。   2.脚气肿痛，牙痛 本品外用有祛湿消肿之功。治湿脚气，可配荷叶、藁本煎汤外洗。单用泡汤漱口，可治牙痛。   ","dosage":"3～6g","effect":"理气止痛，开郁醒脾；外用祛湿消肿。   ","name":"甘松","nature":"辛、甘，温。归脾、胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g。外用适量，泡汤漱口或煎汤洗脚或研末敷患处。   "},{"cat":"","caution":"","classic":"1.胃寒胀痛，肝胃气痛 本品辛香走窜，温通利膈而有行气止痛之功。治疗寒郁中焦，气机不畅，脘腹胀痛或冷痛，可与高良姜、木香、陈皮等同用；治疗肝郁气滞之胸胁胀痛，或肝胃不和之胃脘疼痛，可与香附、延胡索，木香等同用。   2.肾虚阳痿，腰膝酸痛 本品有温肾助阳起痿之功。治肾阳不足，命门火衰，阳痿宫冷，腰膝冷痛，可单用炙热研末服，或配伍淫羊藿、杜仲、巴戟天等。   ","dosage":"3～9g","effect":"理气止痛，温肾助阳。   ","name":"九香虫","nature":"咸，温。归肝、脾、肾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g。   "},{"cat":"","caution":"","classic":"1.虚寒呃逆，呕吐 本品性温沉降，归胃经而能温中、降气、止呃。治中焦虚寒之呕吐、呃逆，可与丁香、柿蒂等同用。   2.肾虚腰痛 本品甘温，入肾经而能温肾助阳。治肾阳虚腰痛，可与杜仲、桑寄生、补骨脂等同用；《重庆草药》单用刀豆2粒，包于猪腰内烧熟食用。   ","dosage":"6～9g","effect":"温中，下气止呃，温肾助阳。   ","name":"刀豆","nature":"甘，温。归胃、肾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，6～9g。   "},{"cat":"","caution":"","classic":"饮食积滞 本品辛以行散消食，甘温健胃和中。用治食积停滞，脘腹胀满，食少纳呆，肠鸣腹泻者，常与山楂、麦芽、莱菔子等同用。又因本品略能解表退热，故尤宜食滞兼外感表证者。  此外，凡丸剂中有金石、贝壳类药物者，前人用本品糊丸以助消化，如磁朱丸（《千金要方》）。   ","dosage":"6～15g","effect":"消食和胃。   ","name":"六神曲","nature":"甘、辛，温。归脾、胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，6～15g。消食宜炒焦用。   "},{"cat":"","caution":"","classic":"附药：建神曲  本品始载于《药性考》，又名泉州神曲、范志曲，简称建曲。为面粉、麸皮和紫苏、荆芥、防风、厚朴、白术、木香、枳实、青皮等四十多种药物，经混合发酵而成。主产于福建泉州。性味苦微温。消食化积功效与六神曲相似，并理气化湿，健脾和中。适用于食滞不化，暑湿泄泻，呕吐不食。煎服，6～15g。","dosage":"6～15g","effect":"","name":"建神曲","nature":"苦微温","parent":"六神曲","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，6～15g"},{"cat":"","caution":"","classic":"食积不消，腹胀口臭，脾胃虚弱，不饥食少 本品消食和中，健脾开胃，作用和缓，助消化而不伤胃气。主治米面薯芋类食积不化和脾虚食滞证，功似麦芽，亦常与麦芽相须为用，以提高疗效。   ","dosage":"9～15g","effect":"消食和中，健脾开胃。   ","name":"稻芽","nature":"甘，温。归脾、胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～15g。炒稻芽偏于消食，用于不饥食少；焦稻芽善化积滞，用于积滞不化。   "},{"cat":"","caution":"不宜入煎剂，因有效成分（鹤草酚）几乎不溶于水。   ","classic":"绦虫病 本品善驱绦虫，对多种绦虫都有驱杀作用，兼能泻下通便，有利于虫体排出，为治绦虫病之专药。单用本品研粉，晨起空腹顿服即效，一般在服药后5～6小时可排出虫体。临床上有仙鹤草芽浸膏，鹤草酚胶囊及鹤草酚的衍生物等多种制剂，治疗绦虫病。  此外，本品制成栓剂，治疗滴虫性阴道炎，有一定疗效。   ","dosage":"30～45g","effect":"杀虫。   ","name":"鹤草芽","nature":"苦、涩，凉。归肝、小肠、大肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"研粉吞服，每次30～45g，小儿0.7～0.8g/kg。每日1次，早起空腹服。   "},{"cat":"凉血止血药","caution":"","classic":"附药：槐角  本品为豆科植物槐Sophora japonica L.的干燥成熟果实，原名槐实。性味苦寒，归肝、大肠经。功能清热泻火，凉血止血。适用于肠热便血，痔疮肿痛出血，肝热头痛眩晕，目赤肿痛。煎服，6～9g。孕妇慎用。","dosage":"6～9g","effect":"清热泻火，凉血止血","name":"槐角","nature":"苦寒，归肝、大肠经","parent":"槐花","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，6～9g"},{"cat":"凉血止血药","caution":"","classic":"1.血热出血 本品味苦涩而性寒，既能凉血止血，又能收敛止血，对于血热所致的咳血、吐血、衄血及紫癜等出血证，可用单味内服，也可配伍其他止血药物。如《本草汇言》治热郁吐血，以本品与麦门冬煎汤饮；《永类钤方》治大便下血，用本品与连皮老姜配伍；《江西民间草药》治内痔出血，以本品与猪肉同煮，去药渣饮汤。   2.疥癣，疮疡，烧烫伤 本品苦寒清泄，既能清热解毒疗疮，又能杀虫止痒，为治癣、疥之良药。用治疥疮，多以鲜品捣敷患处；用治皮癣，《医宗金鉴》以之与枯矾同用，共研末，醋调敷；治烧烫伤，可用鲜品捣敷，或研末油调外涂。   3.热结便秘 本品苦寒，能泻热通便，功似大黄，作用缓和，素有“土大黄”之称。用治热结便秘，可单味煎服，也可与芒硝同用。   ","dosage":"10～15g","effect":"凉血止血，解毒杀虫，泻下通便。   ","name":"羊蹄","nature":"苦、涩，寒。归心、肝、大肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，10～15g；鲜品30～50g，也可绞汁去渣服用；外用适量。   "},{"cat":"凉血止血药","caution":"","classic":"附药：土大黄  本品为蓼科植物巴天酸模Rumex patientia L.或皱叶酸模Rumex crispus L.的干燥根。性味苦、辛，凉；归心、肺经。功能凉血止血，杀虫，通便。适用于衄血，咳血，便血，崩漏，疥癣瘙痒，大便秘结。煎服，9～15g。","dosage":"9～15g","effect":"凉血止血，杀虫，通便","name":"土大黄","nature":"苦、辛，凉；归心、肺经","parent":"羊蹄","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～15g"},{"cat":"化瘀止血药","caution":"","classic":"本品为菊科植物菊三七Gynura segetum （Lour.） Merr.的根或全草，民间习称土三七。性味甘、微苦，平；归肝、胃经。功能散瘀止血，解毒消肿。适用于吐血，衄血，外伤出血，跌打伤痛，痈肿疮疡，蛇虫咬伤。煎服3～10g。外用适量。  ","dosage":"3～10g","effect":"散瘀止血，解毒消肿","name":"菊叶三七","nature":"甘、微苦，平；归肝、胃经","parent":"三七","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服3～10g"},{"cat":"化瘀止血药","caution":"","classic":"本品为景天科植物景天三七Sedum aizoon L.的根或全草。性味甘、微酸，平；归心、肝经。功能散瘀止血，养血安神，解毒消肿。适用于吐血，咳血，衄血，尿血，便血，紫癜，崩漏，外伤出血，跌打伤痛，心悸失眠，烦躁不安，疮肿，蜂蝎蜇伤。煎服，15～30g。外用适量。","dosage":"15～30g","effect":"散瘀止血，养血安神，解毒消肿","name":"景天三七","nature":"甘、微酸，平；归心、肝经","parent":"三七","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～30g"},{"cat":"收敛止血药","caution":"","classic":"1.衄血，咳血，吐血，便血，崩漏，外伤出血 本品味苦涩而性凉，既能收敛止血，又能凉血止血，适用于各种内外伤出血，尤多用于肺胃出血。可单独应用，也可与其他止血药同用。如治咳血、衄血、吐血，可与大蓟、白及等同用；治尿血、血淋，可与小蓟、白茅根等同用；治便血、痔血，可与地榆、槐花等同用；治外伤出血，可单用捣敷或研末敷掺，或以纱布浸紫珠液覆盖压迫局部。   2.热毒疮疡，水火烫伤 本品苦涩性凉，有清热解毒敛疮之功。治热毒疮疡，可单用鲜品捣敷，并煮汁内服，也可配伍其他清热解毒药物。治烧烫伤，用本品研末撒布患处，或用本品煎煮滤取药液，浸湿纱布外敷。   ","dosage":"3～15g","effect":"凉血收敛止血，散瘀解毒消肿。   ","name":"紫珠叶","nature":"苦、涩，凉。归肝、肺、胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～15g；研末吞服1.5～3g。外用适量，敷于患处。   "},{"cat":"收敛止血药","caution":"","classic":"附药：大叶紫珠  本品为马鞭草科植物大叶紫珠Callicarpa macrophylla Vahl的干燥叶或带叶嫩枝。性味辛、苦，平；归肝、肺、胃经。功能散瘀止血，消肿止痛。适用于衄血，咳血，吐血，便血，外伤出血，跌扑肿痛。煎服，15～30g。外用适量，研末敷于患处。","dosage":"15～30g","effect":"散瘀止血，消肿止痛","name":"大叶紫珠","nature":"辛、苦，平；归肝、肺、胃经","parent":"紫珠叶","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～30g"},{"cat":"活血止痛药","caution":"","classic":"附药：片姜黄  本品为姜科植物温郁金Curcuma wenyujin Y.H.Chen etC.Ling的干燥根茎。性味辛、苦，温；归脾、肝经。功能活血行气，通经止痛。适用于胸胁刺痛，胸痹心痛，痛经经闭，癥瘕，风湿肩臂疼痛，跌扑肿痛。煎服3～9g。孕妇慎用。","dosage":"3～9g","effect":"活血行气，通经止痛","name":"片姜黄","nature":"辛、苦，温；归脾、肝经","parent":"姜黄","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服3～9g"},{"cat":"活血调经药","caution":"","classic":"附药：西红花  本品为鸢尾科植物番红花Crocus sativus L.的干燥柱头。又名“藏红花”“番红花”。主产于西班牙，我国上海已引种成功。性味甘、微寒，归心、肝经。功能活血化瘀，凉血解毒，解郁安神。适用于经闭癥瘕，产后瘀阻，温毒发斑，忧郁痞闷，惊悸发狂。1～3g，煎服或沸水泡服。孕妇慎用。","dosage":"","effect":"活血化瘀，凉血解毒，解郁安神","name":"西红花","nature":"甘、微寒，归心、肝经","parent":"红花","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服或沸水泡服"},{"cat":"活血调经药","caution":"","classic":"附药：茺蔚子  本品为唇形科植物益母草Leonurus japonicus Houtt.的干燥成熟果实。性味辛、苦，微寒；归心包、肝经。功能活血调经，清肝明目。适用于月经不调，闭经痛经，目赤翳障，头晕胀痛。煎服，5～10g。瞳孔散大者慎用。","dosage":"5～10g","effect":"活血调经，清肝明目","name":"茺蔚子","nature":"辛、苦，微寒；归心包、肝经","parent":"益母草","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～10g"},{"cat":"活血调经药","caution":"","classic":"本品为苋科植物川牛膝Cyathula officinalis Kuan的干燥根。主产于四川、贵州。性味甘、微苦，平；归肝、肾经。功能逐瘀通经，通利关节，利尿通淋。适用于经闭癥瘕，胞衣不下，跌扑损伤，风湿痹痛，足痿筋挛，尿血血淋。煎服5～10g。孕妇慎用。  ","dosage":"5～10g","effect":"逐瘀通经，通利关节，利尿通淋","name":"川牛膝","nature":"甘、微苦，平；归肝、肾经","parent":"牛膝","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服5～10g"},{"cat":"活血调经药","caution":"","classic":"本品为苋科植物牛膝的野生种及柳叶牛膝Achyranthes longifolia Mak.、粗毛牛膝Achyranthes aspera L.等的干燥根及根茎。主产于湖南、四川、云南、江西。性味苦、酸，平；归肝、肾经。功能活血祛瘀、清热解毒、利尿通淋。适用于血滞闭经，跌打损伤，风湿关节痛，咽喉肿痛，白喉，脚气水肿，血淋涩痛。煎服，10～15g；鲜品加倍；外用适量，捣敷。孕妇慎用。","dosage":"10～15g","effect":"活血祛瘀、清热解毒、利尿通淋","name":"土牛膝","nature":"苦、酸，平；归肝、肾经","parent":"牛膝","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，10～15g；鲜品加倍；外用适量，捣敷"},{"cat":"活血调经药","caution":"用量不宜过大，多服久服可引起腹痛腹泻及便溏。孕妇慎用。   ","classic":"气滞血瘀，月经不调，痛经，闭经，胸胁胀痛 本品质轻升散，独入肝经，既能活血调经，又能疏肝解郁，理气止痛，常用于肝气郁结，气滞血瘀之月经不调、痛经、闭经、胸胁胀痛。可单用开水泡服，亦可与玫瑰花、当归、香附等同用。  此外，本品活血通经、消肿止痛，也可用于跌打伤痛，痈疽肿毒，瘰疬。   ","dosage":"3～6g","effect":"活血调经，疏肝解郁。   ","name":"月季花","nature":"甘，温。归肝经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g。   "},{"cat":"活血调经药","caution":"孕妇慎用。   ","classic":"1.血滞经闭，月经不调，癥瘕，产后乳肿，跌打损伤 本品辛散行血，活血力强，能破瘀血、通经脉、散癥瘕、消肿痛。治血瘀经闭，常配伍当归、红花、赤芍等；治瘀血癥瘕积聚，常配伍配鳖甲、丹皮等，如鳖甲煎丸（《金匮要略》）；治跌打损伤，可单用捣敷，亦可配乳香、没药等药用。   2.风疹发红，皮肤瘙痒，痤疮 本品性寒，既能清热凉血，又能祛风止痒，宜用于血分有热之证。治周身瘙痒，《医学正传》单以本品为末，酒调服，亦可与生地、丹皮、刺蒺藜等同用；治风疹、湿癣，可与防风、苦参、白鲜皮等配伍。   ","dosage":"5～9g","effect":"活血通经，凉血祛风。   ","name":"凌霄花","nature":"甘、酸，寒。归肝、心包经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～9g。外用适量。   "},{"cat":"活血疗伤药","caution":"孕妇禁用；不宜多服久服及生用；运动员慎用；有毒成分能经皮肤吸收，外用不宜大面积涂敷。   ","classic":"1.跌打损伤，骨折肿痛 本品性善通行，功善止痛，为伤科疗伤止痛要药。治跌打损伤，骨折肿痛，常配伍麻黄、乳香、没药等，等份为丸，如九分散（《急救应验良方》）；亦可配伍乳香、红花、血竭等，如八厘散（《医宗金鉴》）；治碰撞损伤、瘀血肿痛，常配伍红花、生半夏、骨碎补等，加醋煎汤，熏洗患处。   2.风湿顽痹，麻木瘫痪 本品善搜筋骨间风湿，开通经络，透达关节，止痛力强，为治疗风湿顽痹、拘挛疼痛、麻木瘫痪之常用药。张锡纯谓其“开通经络，透达关节之力，远胜于他药。”单用有效，亦可配伍麻黄、乳香、全蝎等为丸服。   3.痈疽疮毒，咽喉肿痛 本品苦寒降泄，既能清泄血热，又能散结消肿，且毒性大而能攻毒止痛，可用于痈疽、恶疮、丹毒、咽喉肿痛等。治痈疽疮毒，多作外用，单用即可；治喉痹肿痛，可与山豆根等为末吹喉。   ","dosage":"6g","effect":"通络止痛，散结消肿。   ","name":"马钱子","nature":"苦，温；有大毒。归肝、脾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"0.3～0.6g，炮制后入丸散用。   "},{"cat":"活血疗伤药","caution":"孕妇慎用。月经期不宜服用。   ","classic":"1.跌打损伤，心腹瘀痛 本品味咸入血分，主归心肝经，能活血散瘀，消肿止痛，为伤科及其他瘀滞痛证要药。治跌打损伤，筋骨疼痛，常配伍乳香、没药、儿茶等，如七厘散（《良方集腋》）；治产后瘀滞腹痛，痛经经闭，及瘀血心腹刺痛，常配伍当归、莪术、三棱等。   2.外伤出血 本品既能散瘀，又能止血，有止血不留瘀的特点，适用于瘀血阻滞，血不归经的出血，尤宜外伤出血。既可单用研末外敷患处，亦可配伍儿茶、乳香、没药等，如七厘散（《良方集腋》）。   3.疮疡不敛 本品外用，能活血消肿，祛瘀化腐，敛疮生肌，可治疮疡久溃不敛。单用本品研末外敷，亦可配伍乳香、没药等。   ","dosage":"1～2g","effect":"活血定痛，化瘀止血，生肌敛疮。   ","name":"血竭","nature":"甘、咸，平。归心、肝经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"研末服，1～2g，或入丸剂。外用研末撒或入膏药用。   "},{"cat":"活血疗伤药","caution":"","classic":"附药：北刘寄奴  本品为玄参科植物阴行草Siphonostegia chinensis Bentth.的干燥全草。性味苦，寒；归脾、胃、肝、胆经。功能活血祛瘀，通络止痛，凉血止血，清热利湿。适用于瘀血经闭，月经不调，产后腹痛，癥瘕积聚，跌打伤痛，血痢，血淋，以及湿热黄疸、水肿、带下等。煎服，6～9g。","dosage":"6～9g","effect":"活血祛瘀，通络止痛，凉血止血，清热利湿","name":"北刘寄奴","nature":"苦，寒；归脾、胃、肝、胆经","parent":"刘寄奴","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，6～9g"},{"cat":"温化寒痰药","caution":"","classic":"本品为法半夏、赤小豆、苦杏仁、鲜青蒿、鲜辣蓼、鲜苍耳草与面粉经加工发酵而成。性味甘、微辛，温；归脾、胃经。功能化痰止咳，消食化积。适用于咳嗽痰多，胸脘痞满，呕恶苔腻，以及脾胃虚弱，饮食不消，泄泻，呕吐，腹胀等症。煎服，3～9g。  ","dosage":"3～9g","effect":"化痰止咳，消食化积","name":"半夏曲","nature":"甘、微辛，温；归脾、胃经","parent":"半夏","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g"},{"cat":"温化寒痰药","caution":"","classic":"本品为天南星科植物鞭檐犁头尖Typhonium flagelliforme （Lodd.）Blume 的块茎。主产于广东、广西、云南等地。秋冬采挖块茎，除去外皮及须根，洗净，晒干。性味辛、温，有毒；归脾、肺经。功能燥湿化痰，解毒消肿，止血。适用于咳嗽痰多；外用治痈疮疖肿，无名肿毒，毒虫咬伤，外伤出血。煎服，3～9g；或入丸、散。外用捣敷或研末调敷。","dosage":"3～9g","effect":"燥湿化痰，解毒消肿，止血","name":"水半夏","nature":"辛、温，有毒；归脾、肺经","parent":"半夏","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g；或入丸、散"},{"cat":"温化寒痰药","caution":"","classic":"附药：胆南星  本品为制天南星的细粉与牛、羊或猪胆汁经加工而成，或为生天南星细粉与牛、羊或猪胆汁经发酵而成。性味苦、微辛，凉；归肺、肝、脾经。功能清热化痰，息风定惊。适用于痰热咳嗽、咯痰黄稠、中风痰迷、癫狂惊痫。煎服，3～6g。","dosage":"3～6g","effect":"清热化痰，息风定惊","name":"胆南星","nature":"苦、微辛，凉；归肺、肝、脾经","parent":"天南星","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g"},{"cat":"温化寒痰药","caution":"","classic":"附药：关白附  白附子之名，最早见于《名医别录》。但据考证，历代本草所载者为毛茛科植物黄花乌头Aconitum coreanum （Levl） Raip的干燥块根，称关白附。至于天南星科的独角莲（禹白附）何时收载入药尚不明确。虽然两者在祛风止痉、散结止痛等方面功用相似，但禹白附毒性相对较小，又能解毒散结，现已作为白附子的正品广泛应用；而关白附毒性大，功效偏于散寒祛湿止痛，现已较少应用。","dosage":"","effect":"","name":"关白附","nature":"","parent":"白附子","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""},{"cat":"温化寒痰药","caution":"本品辛温走散，耗气伤阴。久咳肺虚及阴虚火旺者忌用；消化道溃疡、出血者及皮肤过敏者忌用。用量不宜过大，以免引起腹泻。不宜久煎。   ","classic":"1.寒痰咳喘，悬饮胸胁胀痛 本品辛温力雄，性善走散，能温肺寒，利气机，豁痰涎，逐水饮。治寒痰壅肺，气逆咳喘，痰多清稀，胸闷者，常与苏子、莱菔子同用，如三子养亲汤（《韩氏医通》）；若痰饮停滞胸膈成胸胁积水，咳喘胸满胁痛者，可配伍甘遂、大戟等以豁痰逐饮，如控涎丹（《三因方》）。治疗冷哮日久，可与细辛、甘遂、麝香等研末，于夏令外敷肺俞等穴，或以白芥子注射液在肺俞、膻中、定喘等穴位行穴位注射。   2.痰滞经络，关节麻木疼痛，痰湿流注，阴疽肿毒 本品温通经络，善散“皮里膜外之痰”，又能消肿散结止痛。治痰湿阻滞经络之肢体麻木或关节肿痛，可配伍马钱子、没药、肉桂等，亦可单用研末，醋调敷患处。治痰湿流注，阴疽肿毒，常配伍鹿角胶、肉桂、熟地等药，以温阳化滞，消痰散结，如阳和汤（《外科全生集》）。   ","dosage":"3～9g","effect":"温肺豁痰，利气散结，通络止痛。   ","name":"芥子","nature":"辛，温。归肺经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g。外用适量。   "},{"cat":"温化寒痰药","caution":"","classic":"附药：皂角刺  本品为豆科植物皂荚Gleditsia sinensis Lam.的干燥棘刺，又名皂角针。性味辛、温；归肝、胃经。功能消肿托毒，排脓，杀虫。适用于痈疽初起或脓成不溃，外治疥癣麻风。煎服3～10克。外用适量，醋蒸取汁涂患处。","dosage":"","effect":"消肿托毒，排脓，杀虫","name":"皂角刺","nature":"辛、温；归肝、胃经","parent":"皂荚","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服3～10克"},{"cat":"温化寒痰药","caution":"","classic":"附药：金沸草  本品为菊科植物条叶旋覆花Inula linariifolia Turcz.，或旋覆花Inula japonica Thunb.的干燥地上部分。性味苦、辛、咸，温；归肺、大肠经。功能降气，消痰，行水。适用于外感风寒，痰饮蓄积，咳喘痰多，胸膈痞满。煎服，5～10g。","dosage":"5～10g","effect":"降气，消痰，行水","name":"金沸草","nature":"苦、辛、咸，温；归肺、大肠经","parent":"旋覆花","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～10g"},{"cat":"温化寒痰药","caution":"","classic":"1.瘰疬痰核 本品味辛以散，能化痰浊，散郁结，治疗痰火郁结之瘰疬痰核，内服外用均可，多配伍夏枯草、玄参、僵蚕等药。   2.疔疮肿毒，蛇虫咬伤 取本品解毒消肿之效，临床多用鲜品捣敷患处。   ","dosage":"15～30g","effect":"化痰散结，解毒消肿。   ","name":"猫爪草","nature":"甘、辛，温。归肝、肺经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～30g，单味药可用至120g。外用适量，捣敷或研末调敷。   "},{"cat":"清化热痰药","caution":"","classic":"本品为百合科植物平贝母Fritillaria ussuriensis Maxim.的干燥鳞茎。性味苦、甘，微寒；归肺、心经。功能清热润肺，化痰止咳。适用于肺热燥咳，干咳少痰，阴虚劳嗽，咳痰带血。煎服，3～9g；研粉冲服，1次1～2g。本品不宜与川乌、制川乌、草乌、制草乌、附子同用。  ","dosage":"3～9g","effect":"清热润肺，化痰止咳","name":"平贝母","nature":"苦、甘，微寒；归肺、心经","parent":"川贝母","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g；研粉冲服，1次1～2g"},{"cat":"清化热痰药","caution":"","classic":"本品为百合科植物新疆贝母Fritillaria walujewii Regel或伊犁贝母Fritillaria pallidiflora Schrenk的干燥鳞茎。性味苦、甘，微寒；归肺、心经。功能清热润肺，化痰止咳。适用于肺热燥咳，干咳少痰，阴虚劳嗽，咳痰带血。煎服，3～9g。本品不宜与川乌、制川乌、草乌、制草乌、附子同用。","dosage":"3～9g","effect":"清热润肺，化痰止咳","name":"伊贝母","nature":"苦、甘，微寒；归肺、心经","parent":"川贝母","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g"},{"cat":"清化热痰药","caution":"","classic":"本品为百合科植物湖北贝母Fritillaria hupehensis Hsiao et K.C.Hsia的干燥鳞茎。性味微苦，凉；归肺、心经。功能清热化痰，止咳，散结。适用于热痰咳嗽，瘰疬痰核，痈肿疮毒。3～9g，研粉冲服。本品不宜与川乌、制川乌、草乌、制草乌、附子同用。  ","dosage":"","effect":"清热化痰，止咳，散结","name":"湖北贝母","nature":"微苦，凉；归肺、心经","parent":"浙贝母","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""},{"cat":"清化热痰药","caution":"","classic":"本品为葫芦科植物土贝母Bolbostemma paniculatum （Maxim.） Franquet的干燥块茎。性味苦，微寒；归肺、脾经。功能解毒，散结，消肿。适用于乳痈，瘰疬，痰核。煎服，5～10g。","dosage":"5～10g","effect":"解毒，散结，消肿","name":"土贝母","nature":"苦，微寒；归肺、脾经","parent":"浙贝母","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～10g"},{"cat":"清化热痰药","caution":"","classic":"本品为葫芦科植物栝楼 Trichosanthes kirilowii Maxim.或双边栝楼Trichosanthes rosthornii Harms的干燥成熟果皮。性味甘，寒；归肺、胃经。功能清热化痰，利气宽胸。适用于痰热咳嗽，胸闷胁痛。煎服，6～10g。不宜与川乌、制川乌、草乌、制草乌、附子同用。  ","dosage":"6～10g","effect":"清热化痰，利气宽胸","name":"瓜蒌皮","nature":"甘，寒；归肺、胃经","parent":"瓜蒌","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，6～10g"},{"cat":"清化热痰药","caution":"","classic":"本品为葫芦科植物栝楼 Trichosanthes kirilowii Maxim.或双边栝楼Trichosanthes rosthornii Harms的干燥成熟种子。性味甘，寒；归肺、胃、大肠经。功能润肺化痰，滑肠通便。适用于燥咳痰黏，肠燥便秘。煎服，9～15g。不宜与川乌、制川乌、草乌、制草乌、附子同用。","dosage":"9～15g","effect":"润肺化痰，滑肠通便","name":"瓜蒌子","nature":"甘，寒；归肺、胃、大肠经","parent":"瓜蒌","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～15g"},{"cat":"清化热痰药","caution":"","classic":"附药：罗汉果  本品为葫芦科植物罗汉果Siraitia grosvenorii （Swingle）C. Jeffrey ex A. M. Lu et Z. Y. Zhang的干燥果实。主产于广西。秋季果实由嫰绿色变深绿色时采收，晾数天后，低温干燥。性味甘，凉；归肺、大肠经。功能清热润肺，利咽开音，滑肠通便。适用于肺热燥咳，咽痛失音，肠燥便秘。煎服，9～15g。","dosage":"9～15g","effect":"清热润肺，利咽开音，滑肠通便","name":"罗汉果","nature":"甘，凉；归肺、大肠经","parent":"胖大海","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～15g"},{"cat":"清化热痰药","caution":"本品有毒，不宜过量、久服。多服、久服可引起吐泻腹痛等消化道反应，并对肝肾有一定损害，故脾胃虚弱及肝肾功能损害者慎用。   ","classic":"1.瘿瘤 本品苦寒泄降，功擅化痰软坚，散结消瘿，为治痰火互结所致瘿瘤之要药。《斗门方》治项下气瘿结肿，单以本品浸酒饮；亦可与海藻、牡蛎等配伍。现代常用于治疗多种甲状腺肿大。   2.疮疡肿毒，咽喉肿痛，毒蛇咬伤 本品苦寒入血分，能凉血降火解毒。治疮疡肿毒，常与金银花、紫花地丁等清热解毒药配伍，也可单用捣烂外敷；用于热毒咽喉肿痛，常与射干、山豆根、大青叶等同用；用于毒蛇咬伤，则与半枝莲、白花蛇舌草、重楼等同用内服或外敷。近年来常用本品配伍薏苡仁、山慈菇等，用治消化系统及甲状腺肿瘤，有一定效果。  此外，本品还有凉血止血作用，可用于血热所致的吐血，衄血，咳血等；并兼有止咳平喘作用，亦可治咳嗽、气喘、百日咳等。   ","dosage":"5～15g","effect":"化痰散结消瘿，清热凉血解毒。   ","name":"黄药子","nature":"苦，寒；有毒。归肺、肝、心经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～15g；研末服，1～2g。外用适量，鲜品捣敷，或研末调敷，或磨汁涂。   "},{"cat":"止咳平喘药","caution":"","classic":"附药：甜杏仁  本品为蔷薇科植物杏Prunus armeniaca L.及其栽培变种的干燥成熟味甜的种子。性味甘，平；归肺、大肠经。功能润肺止咳，润肠通便。适用于虚劳咳嗽，肠燥便秘。煎服，5～10g。","dosage":"5～10g","effect":"润肺止咳，润肠通便","name":"甜杏仁","nature":"甘，平；归肺、大肠经","parent":"苦杏仁","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～10g"},{"cat":"止咳平喘药","caution":"本品含马兜铃酸，长期、大剂量服用可引起肾脏损害等不良反应；儿童及老年人慎用；孕妇、婴幼儿及肾功能不全者禁用。   ","classic":"1.肺热咳喘，痰中带血 本品味苦降泄，性寒清热，兼可化痰，故善降肺气、清痰火而止咳平喘，凡一切咳嗽痰喘属于肺热、燥热者皆可用之。治疗痰热壅肺，咳喘胸满，痰黄质稠，常与桑白皮、葶苈子、半夏同用，以泻肺平喘、化痰降逆；若肺热阴虚咳喘，痰少咽干口渴，常与麦冬、天冬、知母等同用，以清热养阴、润肺止咳；若虚火内炽，痰中带血，常与阿胶、牛蒡子、苦杏仁等同用，如补肺阿胶汤（《小儿药证直诀》）。   2.肠热痔血，痔疮肿痛 本品又能清泄大肠实热，用治大肠壅热所致的痔疮肿痛、出血，可单用本品煎汤内服，或熏洗患处，也可与槐角、地榆等同用，熏洗局部，以消肿止痛，凉血止血。   ","dosage":"3～9g","effect":"清肺降气，止咳平喘，清肠消痔。   ","name":"马兜铃","nature":"苦，微寒。归肺、大肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g。外用适量，煎汤熏洗。肺虚久咳蜜炙用，其余生用。   "},{"cat":"止咳平喘药","caution":"","classic":"本品为马兜铃科植物马兜铃Aristolochia debilis Sieb. et Zucc.和北马兜铃Aristolochia contorta Bge. 的干燥根。性味辛、苦、寒，小毒；归肝、胃经。功能行气止痛，解毒消肿。适用于肝胃气滞之胸胁脘腹疼痛，泻痢腹痛，疔疮肿毒，皮肤湿疮，毒蛇咬伤。煎服，3～9g；研末服，1.5～2g。外用适量，研末调敷或磨汁涂。本品过量服用可引起恶心、呕吐等胃肠道反应；又因含马兜铃酸，过量或长期服用可损伤肾功能，故不宜过量或持续内服，脾胃虚寒者慎服，肾病患者忌服。  ","dosage":"3～9g","effect":"行气止痛，解毒消肿","name":"青木香","nature":"辛、苦、寒，小毒；归肝、胃经","parent":"马兜铃","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g；研末服，1.5～2g"},{"cat":"止咳平喘药","caution":"","classic":"本品为马兜铃科植物马兜铃Aristolochia debilis Sieb.et Zucc.，或北马兜铃Aristolochia contorta Bge的干燥地上部分。性味苦，温；归肝、脾、肾经。功能行气活血，通络止痛。适用于气滞血瘀之脘腹刺痛，风湿痹痛。煎服，3～6g。本品含马兜铃酸，可引起肾脏损害等不良反应，儿童及老年人慎用；孕妇、婴幼儿及肾功能不全者忌服。","dosage":"3～6g","effect":"行气活血，通络止痛","name":"天仙藤","nature":"苦，温；归肝、脾、肾经","parent":"马兜铃","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g"},{"cat":"止咳平喘药","caution":"","classic":"附药：银杏叶  本品为银杏科植物银杏Ginkgo biloba L.的干燥叶。性味甘、苦、涩，平；归心、肺经。功能活血化瘀，通络止痛，敛肺平喘，化浊降脂。适用于瘀血阻络，胸痹心痛，中风偏瘫，肺虚咳喘，高脂血症。煎服，9～12g。有实邪者忌用。","dosage":"9～12g","effect":"活血化瘀，通络止痛，敛肺平喘，化浊降脂","name":"银杏叶","nature":"甘、苦、涩，平；归心、肺经","parent":"白果","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～12g"},{"cat":"止咳平喘药","caution":"","classic":"1.新久咳嗽，喘满痰多 本品长于祛痰止咳，略兼平喘。因其性平，治咳喘，无论新久、寒热，均可配伍应用。治疗肺热咳喘，咯痰黄稠，可单味煎服，或配伍枇杷叶、黄芩、桑白皮等药，以清肺化痰，止咳平喘；若寒痰咳喘，痰多质稀，常配伍麻黄、细辛、干姜等药，以温肺化痰、止咳平喘。治肺痈咳吐脓痰，胸痛，常配伍鱼腥草、薏苡仁、芦根等药，以清泄肺热、祛痰排脓。   2.湿热黄疸 本品能清利湿热，治湿热黄疸，常与茵陈、虎杖、栀子等同用，以清热除湿、利胆退黄。   3.瘀阻经闭，风湿痹痛，跌打损伤 本品能活血化瘀，通经止痛。治血瘀经闭、痛经，可配桃仁、红花、丹参等活血调经药。治风湿痹痛，可配独活、威灵仙、防己等祛风湿通络药。治跌打伤痛，可单用本品，水、酒各半煎服，或与红花、乳香、没药等活血化瘀药同用。   ","dosage":"15～30g","effect":"化痰止咳，清利湿热，活血化瘀。   ","name":"矮地茶","nature":"辛、微苦，平。归肺、肝经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～30g。   "},{"cat":"止咳平喘药","caution":"孕妇、外感及痰热咳喘、青光眼、高血压、心动过速者禁用。   ","classic":"1.哮喘咳嗽 本品辛温有毒，平喘止咳力强，适用于喘咳无痰或痰少，它药乏效者，尤宜于寒性哮喘，可作散剂单用，或切丝制成卷烟燃吸，或配入复方中应用。   2.小儿慢惊风，癫痫 本品有定惊解痉作用，治疗小儿慢惊风、癫痫之痉挛抽搐，常与天麻、全蝎、天南星等药同用。   3.脘腹冷痛，风湿痹痛 本品辛散温通，有良好的麻醉止痛作用，可广泛用于各种疼痛。如治脘腹疼痛，可单味水煎或作散剂内服。治风湿痹痛，跌打伤痛，单用即可，也可与川芎、当归、姜黄等药同用，以加强活血止痛之效。   4.外科麻醉 古代以本品作麻醉剂，常与川乌、草乌、姜黄等同用，如整骨麻药方（《医宗金鉴》）。现代也作为外科麻醉使用。   ","dosage":"6g","effect":"平喘止咳，解痉定痛。   ","name":"洋金花","nature":"辛，温；有毒。归肺、肝经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"内服，0.3～0.6g，宜入丸、散；亦可作卷烟分次燃吸（1日用量不超过1.5g）。外用适量。   "},{"cat":"重镇安神药","caution":"","classic":"附药：龙齿  本品为古代哺乳动物如三趾马类、犀类、鹿类、牛类、象类等的牙齿化石。性味甘、涩，凉；归心、肝经。功能镇惊安神，主治惊痫癫狂、心悸怔忡、失眠多梦。煎服，15～30g，先煎。","dosage":"15～30g","effect":"镇惊安神，主治惊痫癫狂、心悸怔忡、失眠多梦","name":"龙齿","nature":"甘、涩，凉；归心、肝经","parent":"龙骨","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，15～30g，先煎"},{"cat":"养心安神药","caution":"","classic":"1.失眠多梦 本品味甘，入心、肝二经，能补养阴血，养心安神，宜于阴虚血少之失眠多梦，心神不宁，常与合欢皮、酸枣仁、柏子仁等养心安神药同用；若与珍珠母、龙骨、牡蛎等潜阳安神药配伍，可用治失眠，阴虚阳亢者。   2.血虚身痛，风湿痹痛 本品能养血祛风，通经活络，用治血虚身痛，常与鸡血藤、当归、川芎等补血活血，通经止痛药配伍；用治风湿痹痛，常与羌活、独活、桑寄生等祛风湿、止痹痛药同用。   3.皮肤瘙痒 本品有养血祛风止痒之功，可用治风疹、疥癣之皮肤瘙痒，常与蝉蜕、浮萍、地肤子等药同用。   ","dosage":"9～15g","effect":"养血安神，祛风通络。   ","name":"首乌藤","nature":"甘，平。归心、肝经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～15g。外用适量，煎水洗患处。   "},{"cat":"养心安神药","caution":"","classic":"附药：合欢花  本品为豆科植物合欢Albizia julibrissin Durazz.的干燥花序或花蕾。前者习称“合欢花”，后者习称“合欢米”。性味甘，平；归心、肝经。功能解郁安神。适用于心神不安，忧郁失眠。煎服，5～10g。","dosage":"5～10g","effect":"解郁安神","name":"合欢花","nature":"甘，平；归心、肝经","parent":"合欢皮","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～10g"},{"cat":"平抑肝阳药","caution":"脾胃虚弱者慎用。   ","classic":"1.肝阳上亢，头晕目眩 本品味咸性平，主入肝经，有平肝潜阳之功。治疗肝阳上亢，头晕目眩，多与石决明、牡蛎、磁石等镇潜肝阳药同用，以增强平肝潜阳之力。   2.惊悸失眠 本品既能平肝潜阳，又能镇惊安神，适用于肝阳上扰，心阳躁动之惊悸心烦，失眠多梦者，可与龙骨、磁石、茯神等安神药配伍，共收安神、平肝之效。亦可用治小儿急惊风，高热不退、手足抽搐，常与羚羊角、钩藤、天麻等药同用。   3.目赤翳障，目昏眼花 本品有清肝明目之效，用治肝热目赤肿痛，目生翳膜，视物昏花等症，可与菊花、蝉蜕、夏枯草等清肝明目药配伍。   ","dosage":"10～15g","effect":"平肝潜阳，镇惊安神，清肝明目。   ","name":"紫贝齿","nature":"咸，平。归肝经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，10～15g；先煎，或研末入丸、散剂。   "},{"cat":"息风止痉药","caution":"","classic":"附药：山羊角  本品为牛科动物青羊Naemorhedus goral Ltardwicke的角。性味咸，寒；归肝经。功能平肝，镇惊。适用于肝阳上亢、头晕目眩，肝火上炎、目赤肿痛，惊风抽搐。本品功用与羚羊角相似而药力较弱，可作为羚羊角的代用品使用。煎服，10～15g。","dosage":"10～15g","effect":"平肝，镇惊","name":"山羊角","nature":"咸，寒；归肝经","parent":"羚羊角","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，10～15g"},{"cat":"息风止痉药","caution":"","classic":"本品以牛科动物牛Bos taurus domesticus Gmelin的新鲜胆汁作母液，加入去氧胆酸、胆酸、复合胆红素钙等制成。本品性味归经、功能主治、用法用量、使用注意与牛黄相同。偶有轻度消化道不适。  ","dosage":"","effect":"主治、用法用量、使用注意与牛黄相同","name":"体外培育牛黄","nature":"归经、功能主治、用法用量、使用注意与牛黄相同","parent":"牛黄","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"用量、使用注意与牛黄相同"},{"cat":"息风止痉药","caution":"","classic":"本品由牛胆粉、胆酸、猪去氧胆酸、牛磺酸、胆红素、胆固醇、微量元素等加工制成。性味苦，凉。归心、肝经。功能清热解毒，化痰定惊。适用于痰热谵狂，神昏不语，小儿急惊风，咽喉肿痛，口舌生疮，痈肿疔疮。1次0.15～0.35g，多入配方用。外用适量敷患处。非实热证不宜用。孕妇慎用。","dosage":"","effect":"清热解毒，化痰定惊","name":"人工牛黄","nature":"苦，凉","parent":"牛黄","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""},{"cat":"息风止痉药","caution":"","classic":"附药：密环菌  本品为白蘑科真菌假蜜环菌Armillariella mellea （Vahl.ex Fr.） Karst.的子实体。性味甘，平；归肝经。功能平肝息风，祛风通络，强筋壮骨。适用于肝阳上亢、头晕头痛、失眠，以及风湿痹证、四肢麻木、腰腿疼痛等。煎服，30～60g。密环菌为天麻种子和块茎均赖于供给营养而生长的一种发光真菌，因其具有与天麻相似的药理作用和临床疗效，故可作为天麻的代用品使用。","dosage":"30～60g","effect":"平肝息风，祛风通络，强筋壮骨","name":"密环菌","nature":"甘，平；归肝经","parent":"天麻","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，30～60g"},{"cat":"息风止痉药","caution":"","classic":"本品为蚕蛾科昆虫家蚕蛾Bombyx mori Linnaeus的蚕蛹经白僵菌Beauveria bassiana （Bals.） Vaillant发酵的制成品。性味咸、辛，平；归肝、肺、胃经。功能清热镇惊，化痰止咳，消肿散结。适用于高热惊风，痉挛抽搐，癫痫，急性咽炎，流行性腮腺炎，急、慢性支气管炎，荨麻疹，高脂血症等。研末内服，1.5～6g；或制成片剂用。本品的效用与僵蚕相近而药力较缓，可作僵蚕的代用品。  ","dosage":"","effect":"清热镇惊，化痰止咳，消肿散结","name":"僵蛹","nature":"咸、辛，平；归肝、肺、胃经","parent":"僵蚕","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""},{"cat":"息风止痉药","caution":"","classic":"本品为蚕蛾科昆虫家蚕蛾Bombyx mori Linnaeus 的雄虫的全体。性味咸，温；归肝、肾经。功能补肾壮阳，涩精，止血，解毒消肿。适用于阳痿遗精，白浊，血淋，金疮出血，咽喉肿痛，口舌生疮，痈肿疮毒，冻疮，蛇伤等。研末内服，1.5～5g；或入丸剂用；外用适量。","dosage":"","effect":"补肾壮阳，涩精，止血，解毒消肿","name":"雄蚕蛾","nature":"咸，温；归肝、肾经","parent":"僵蚕","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""},{"cat":"","caution":"","classic":"附药：人工麝香  本品由麝香酮、芳活素、海可素Ⅰ和海可素Ⅱ等加工制成。性味辛、温。归心、脾经。功能开窍醒神，活血通经，消肿止痛。适用于热病神昏，中风痰厥，气郁暴厥，中恶昏迷， 经闭，癥瘕，难产死胎，胸痹心痛，心腹暴痛，跌扑伤痛，痹痛麻木，痈肿瘰疬，咽喉肿痛。0.06～0.1g，入丸散，不宜入煎剂。外用适量。孕妇禁用。本品有与天然麝香基本相似的疗效，现已用于临床，代替天然麝香，以弥补麝香药源的不足。","dosage":"","effect":"开窍醒神，活血通经，消肿止痛","name":"人工麝香","nature":"辛、温","parent":"麝香","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""},{"cat":"","caution":"","classic":"附药：九节菖蒲  古代本草文献称石菖蒲以“一寸九节者良”，故石菖蒲亦称九节菖蒲。但现代商品药材所用之九节菖蒲为毛茛科植物阿尔泰银莲花Anemone altaica Fisch.ex C.A.Mey的根茎，主产于陕西、山西、河南等地。5～6月叶枯倒苗前采挖，除去泥沙，晒干后搓去须根，簸去杂质，洗净，干燥，生用。其性味辛，温；归心、肝、脾经。功能化痰开窍，安神，宣湿醒脾，解毒。适用于热病神昏，癫痫，气闭耳聋，多梦健忘，胸闷腹胀，食欲不振，风湿痹痛，痈疽，疥癣。煎服，1.5～6g；或入丸、散，或鲜品捣汁服。外用适量，煎水洗；或鲜品捣敷；或研末调敷。阴虚阳亢，烦躁汗多，滑精者慎服。实验研究表明，现代商品药材所用之九节菖蒲有一定毒性，故临床使用时二者不可混淆。","dosage":"5～6g","effect":"化痰开窍，安神，宣湿醒脾，解毒","name":"九节菖蒲","nature":"辛，温；归心、肝、脾经","parent":"石菖蒲","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，1.5～6g；或入丸、散，或鲜品捣汁服"},{"cat":"补气药","caution":"","classic":"本品为五加科植物人参Panax ginseng C.A.Mey.的栽培品经蒸制后的干燥根及根茎。性味甘、微苦，微温；归脾、肺、心、肾经。功能大补元气，复脉固脱，益气摄血，适用于体虚欲脱，肢冷脉微，气不摄血，崩漏下血。煎服，3～9g，另煎兑服。不宜与藜芦、五灵脂同用。  ","dosage":"3～9g","effect":"大补元气，复脉固脱，益气摄血，适用于体虚欲脱，肢冷脉微，气不摄血，崩漏下血","name":"红参","nature":"甘、微苦，微温；归脾、肺、心、肾经","parent":"人参","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g，另煎兑服"},{"cat":"补气药","caution":"","classic":"本品为五加科植物人参Panax ginseng C.A.Mey.的干燥叶。味苦、甘，性寒；归肺、胃经。功能补气，益肺，祛暑，生津。适用于气虚咳嗽，暑热烦躁，津伤口渴，头目不清，四肢倦乏。煎服，3～9g。不宜与藜芦、五灵脂同用。","dosage":"3～9g","effect":"补气，益肺，祛暑，生津","name":"人参叶","nature":"","parent":"人参","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g"},{"cat":"补气药","caution":"","classic":"附药：红芪  本品为豆科植物多序岩黄芪Hedysarum polybotrys Hand.-Mazz.的干燥根。主产于甘肃南部地区。春、秋二季采挖，除去须根和根头，晒干。味甘，性微温；归肺、脾经。功能补气升阳，固表止汗，利水消肿，生津养血，行滞通痹，托毒排脓，敛疮生肌。适用于气虚乏力，食少便溏，中气下陷，久泻脱肛，便血崩漏，表虚自汗，气虚水肿，内热消渴，血虚萎黄，半身不遂，痹痛麻木，痈疽难溃，久溃不敛。煎服，9～30g。炙红芪功能益气补中，用于气虚乏力，食少便溏。","dosage":"9～30g","effect":"补气升阳，固表止汗，利水消肿，生津养血，行滞通痹，托毒排脓，敛疮生肌","name":"红芪","nature":"","parent":"黄芪","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～30g"},{"cat":"补气药","caution":"","classic":"本品为豆科植物扁豆Dolichos lablab L.的种皮。性能功效与扁豆相似而健脾之力略逊，但无壅滞之弊，偏于化湿。主治脾虚有湿或暑湿所致的吐泻及脚气浮肿。煎服，5～10g。  ","dosage":"5～10g","effect":"","name":"扁豆衣","nature":"","parent":"白扁豆","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～10g"},{"cat":"补气药","caution":"","classic":"本品为豆科植物扁豆Dolichos lablab L.的花。性味甘、淡，平。归脾、胃经。功能消暑化湿。多用于暑湿泄泻及湿热带下。煎服，5～10g。","dosage":"5～10g","effect":"消暑化湿","name":"扁豆花","nature":"甘、淡，平","parent":"白扁豆","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～10g"},{"cat":"补气药","caution":"","classic":"1.脾肺气虚，体虚乏力，食欲不振 本品甘温，归脾、肺经，功能补脾气，益肺气，治脾肺气虚，体虚乏力，食欲不振，大便溏泻，短气懒言，可与黄芪、太子参、白术等同用。   2.肺肾两虚，久咳虚喘 本品能益肺补肾，并略有祛痰平喘之力。治疗肺肾两虚，久咳虚喘，可与人参、蛤蚧、五味子等药配伍。   3.肾虚腰膝酸痛 本品归肾经，有温肾助阳，强健筋骨之功。治肾阳不足，筋骨失于温养而见腰膝酸痛者，可单用，或与杜仲、桑寄生等药同用。亦可用于阳痿、小儿行迟及风湿痹证而兼肝肾不足者。   4.心脾不足，失眠多梦 本品归心、脾经，能补益心脾之气，并安神益志。治心脾两虚，心神失养的失眠、多梦、健忘，可与酸枣仁、远志、石菖蒲等养心安神之品配伍。   ","dosage":"9～27g","effect":"益气健脾，补肾安神。   ","name":"刺五加","nature":"甘、微苦，温。归脾、肺、肾、心经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～27g。   "},{"cat":"补气药","caution":"","classic":"1.脾虚证 本品味甘入脾经，能益气健脾。治脾胃气虚，体倦乏力，纳食不佳者，可配伍白术、茯苓等健脾益气药。因其性偏苦寒，兼能生津止渴，故较适宜于脾胃气阴两伤，口渴、咽干、心烦者，可与太子参、山药、南沙参等益气养阴药同用。   2.肺虚咳嗽 本品入肺经，能益肺气，清肺热，兼有化痰止咳之功。适用于气阴两虚，肺中燥热，咳嗽痰黏者，可与川贝母、百合等养阴润肺、化痰止咳药同用。若肺气虚而痰湿内盛，咳嗽痰多者，亦可与半夏、陈皮等燥湿化痰药同用。  此外，本品还略有清热解毒作用，可用于肿瘤而有热毒之证。   ","dosage":"10～20g","effect":"益气健脾，化痰止咳，清热解毒。   ","name":"绞股蓝","nature":"甘、苦，寒。归脾、肺经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，10～20g；亦可泡服。   "},{"cat":"补气药","caution":"","classic":"1.气虚血瘀，胸痹心痛，中风偏瘫 本品能益气活血，通脉止痛。适用于气虚血瘀所致的胸痹心痛，心悸气短，神疲乏力，少气懒言，可与黄芪、三七等药配伍。治疗中风恢复期后遗症，半身不遂，偏身麻木，言语不清，口舌歪斜，若属于气虚血瘀者，多配伍黄芪、川芎、地龙等药；若属于肝肾不足者，可配伍杜仲、续断、肉桂等药。   2.脾肺气虚，倦怠气喘 本品味甘，入肺、脾经，能益气健脾，平喘止咳。治疗脾气虚弱，倦怠乏力，可配伍白术、山药等药。治疗肺虚喘咳，可与人参、黄芪、五味子等药同用；若肺阴不足，咳嗽痰黏，或有咳血者，可配伍南沙参、麦冬、百合等药。   ","dosage":"3～6g","effect":"益气活血，通脉平喘。   ","name":"红景天","nature":"甘、苦，平。归肺、脾、心经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g。   "},{"cat":"补气药","caution":"","classic":"1.脾虚食少，食积腹痛 本品甘酸而温，归脾、胃经，既能温养脾气，开胃消食，又可化阴生津。适用于脾气虚弱或脾胃气阴两伤，食少纳差，消化不良，脘腹胀痛，体倦乏力者，《四部医典》以之与芫荽子、藏木香、余甘子等同用。   2.咳嗽痰多 本品入肺经，能止咳祛痰，为藏医、蒙医治疗咳喘痰多的常用药。可以单用，如《四部医典》以沙棘适量，煎煮浓缩为膏。亦可配伍余甘子、白葡萄、甘草等止咳祛痰药，如五味沙棘散（《青海省藏药标准》）。   3.瘀血经闭，胸痹心痛，跌扑瘀肿 本品有活血化瘀作用，可用治妇女经闭，月经不调，胸痹心痛，跌打损伤等多种瘀血证，可与川芎、三七、丹参等药配伍。   ","dosage":"3～10g","effect":"健脾消食，止咳祛痰，活血散瘀。   ","name":"沙棘","nature":"甘、酸、涩，温。归脾、胃、肺、心经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～10g。   "},{"cat":"补气药","caution":"","classic":"附药：蜂胶  本品为蜜蜂科昆虫意大利蜜蜂 Apis mellifera Linnaeus的干燥分泌物。味苦、辛，性寒；归脾、胃经。功能补虚弱，化浊脂，止消渴；外用解毒消肿，收敛生肌。适用于体虚早衰，高脂血症，消渴；外治皮肤皲裂，烧烫伤。0.2～0.6g，多入丸散服，或加蜂蜜适量冲服。外用适量。","dosage":"","effect":"补虚弱，化浊脂，止消渴；外用解毒消肿，收敛生肌","name":"蜂胶","nature":"","parent":"蜂蜜","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""},{"cat":"补阳药","caution":"","classic":"本品为鹿科动物马鹿Cervus elaphus Linnaeus或梅花鹿Cervus nippon Temminck已骨化的角或锯茸后翌年春季脱落的角基，分别习称“马鹿角”“梅花鹿角”“鹿角脱盘”。性味咸、温；归肾、肝经。功能温肾阳，强筋骨，行血消肿。适用于肾阳不足，阳痿遗精，腰脊冷痛，阴疽疮疡，乳痈初起，瘀血肿痛。煎服，6～15g。阴虚火旺者忌服。  ","dosage":"6～15g","effect":"温肾阳，强筋骨，行血消肿","name":"鹿角","nature":"咸、温；归肾、肝经","parent":"鹿茸","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，6～15g"},{"cat":"补阳药","caution":"","classic":"本品为鹿角经水煎煮、浓缩制成的固体胶。性味甘、咸，温；归肾、肝经。功能温补肝肾，益精养血。适用于肝肾不足所致的腰膝酸冷，阳痿遗精，虚劳羸瘦，崩漏下血，便血尿血，阴疽肿痛。3～6g，烊化兑服。阴虚火旺者忌服。  ","dosage":"","effect":"温补肝肾，益精养血","name":"鹿角胶","nature":"甘、咸，温；归肾、肝经","parent":"鹿茸","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""},{"cat":"补阳药","caution":"","classic":"本品为鹿角去胶质的角块。味咸、涩，性温；归肝、肾经。功能温肾助阳，收敛止血。适用于脾肾阳虚，白带过多，遗尿尿频，崩漏下血，疮疡不敛。煎服，9～15g，先煎。阴虚火旺者忌服。","dosage":"9～15g","effect":"温肾助阳，收敛止血","name":"鹿角霜","nature":"","parent":"鹿茸","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～15g，先煎"},{"cat":"补阳药","caution":"","classic":"附药：脐带  本品为胎儿的脐带。系将新鲜脐带洗净，用金银花、甘草及黄酒同煮，烘干入药。性味甘、咸，温；归肾经。功能补肾，纳气，敛汗。主治肾虚喘咳、盗汗。煎服，1～2条；研末服，1.5～3g。","dosage":"5～3g","effect":"补肾，纳气，敛汗","name":"脐带","nature":"甘、咸，温；归肾经","parent":"紫河车","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，1～2条；研末服，1.5～3g"},{"cat":"补阳药","caution":"","classic":"附药：杜仲叶  本品为杜仲科植物杜仲Eucommia ulmoides Oliv.的干燥叶。性味微辛，温；归肝、肾经。功能补肝肾，强筋骨。适用于肝肾不足，头晕目眩，腰膝酸痛，筋骨痿软。煎服，10～15g。","dosage":"10～15g","effect":"补肝肾，强筋骨","name":"杜仲叶","nature":"微辛，温；归肝、肾经","parent":"杜仲","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，10～15g"},{"cat":"补阳药","caution":"阴虚火旺者忌用。不宜久服。   ","classic":"肾阳亏虚，阳痿不举，宫冷不孕 本品温肾壮阳起痿，宜于肾阳亏虚，男子阳痿遗精，女子宫冷不孕，崩中漏下，以及腰膝冷痛等症，可单用本品或入复方。如治阳痿阴汗，《普济方》用本品煅后研末，空心盐汤送服；治下元虚冷，精滑不禁，便溏足冷，《杂病源流犀烛》用本品煅后，与钟乳石等分为细末，加酒煮附子末，面糊为丸，空腹米汤送下；治精清精冷无子，可与鹿茸、菟丝子、肉苁蓉等配伍；治子宫虚寒不孕，可与吴茱萸、艾叶、阿胶等配伍。   ","dosage":"3～6g","effect":"温肾壮阳。   ","name":"阳起石","nature":"咸，温。归肾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g。   "},{"cat":"补阳药","caution":"阴虚火旺、肺热咳喘者忌用。   ","classic":"1.肾阳亏虚，宫冷不孕，崩漏带下 本品甘温，能助肾阳，暖胞宫，调冲任，常用治元阳衰惫，血海虚寒，宫冷不孕、崩漏带下诸证，常与当归、熟地、川芎、香附、白术等配伍。   2.惊悸不安，失眠多梦 本品入心经，能镇心安神。治心悸怔忡，虚烦失眠，可与酸枣仁、柏子仁、当归等同用；治心经痰热，惊痫抽搐，可与龙骨、寒水石、大黄等配伍，。   3.虚寒咳喘 本品温肺寒，止喘嗽。《青囊秘方》单用本品火煅，花椒泡汤，治肺寒气逆，痰多喘咳症；治肺气不足，短气喘乏，口出如含冰雪，语言不出者，可与五味子、款冬花、人参等配伍。   ","dosage":"9～15g","effect":"温肾暖宫，镇心安神，温肺平喘。   ","name":"紫石英","nature":"甘，温。归肾、心、肺经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～15g，先煎。   "},{"cat":"补阳药","caution":"阴虚火旺及骨蒸劳嗽等忌用。   ","classic":"1.肾阳亏虚，阳痿精冷，精少不育 本品性热壮阳，咸以入肾，为血肉有情之品，有补肾壮阳，益精补髓之功。治肾阳亏虚，腰膝痿弱，阳痿不举，精寒不育，尿频便溏，腹中冷痛等症，常与人参、鹿茸、附子等药同用。治疗精少不育之症，可与鹿茸、紫河车、人参等同用。   2.肾阳衰微，心腹冷痛 本品长于补肾壮阳，用治肾阳衰微，下元久冷，虚寒攻冲，心腹冷痛，可配伍吴茱萸、甘松、高良姜等，共收补阳散寒之功。   ","dosage":"1～3g","effect":"暖肾壮阳，益精补髓。   ","name":"海狗肾","nature":"咸，热。归肾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"研末服，每次1～3g，每日2～3次。   "},{"cat":"补阳药","caution":"","classic":"附药：黄狗肾  本品为哺乳动物犬科黄狗Canis familiaris L.的阴茎和睾丸。又名狗鞭。性味咸，温；归肾经。功能壮阳益精。适用于肾虚精亏，阳痿宫冷，健忘耳鸣，神思恍惚，腰酸足软。研粉冲服或入丸、散剂服，1～3g。鲜品可加调料煮熟服食。阴虚火旺者不宜用。","dosage":"","effect":"壮阳益精","name":"黄狗肾","nature":"咸，温；归肾经","parent":"海狗肾","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""},{"cat":"补阳药","caution":"","classic":"附药：海龙  本品为海龙科动物刁海龙Solenognathus hardwickii （Gray）、拟海龙Syngnathoides biaculeatus （Bloch）或尖海龙Syngnathus acus Linnaeus的干燥体。性味甘、咸，温；归肝、肾经。功能温肾壮阳，散结消肿。适用于肾阳不足，阳痿遗精，癥瘕积聚，瘰疬痰核，跌扑损伤；外治痈肿疔疮。煎服，3～9g。外用适量，研末敷患处。","dosage":"3～9g","effect":"温肾壮阳，散结消肿","name":"海龙","nature":"甘、咸，温；归肝、肾经","parent":"海马","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g"},{"cat":"补阳药","caution":"","classic":"1.病后体虚，神疲乏力，心悸失眠，盗汗 本品入肺、肾二经，善于补益肺肾，有强壮体魄，补虚抚羸之能。治病后、产后，伤血耗气，虚弱羸瘦，体虚盗汗等症，可单用；治盗汗症可与党参、黄芪、熟地黄等配伍。   2.痨嗽咳血 本品补肺益肾，治肺肾阴伤，劳嗽咳血，以本品与白木耳蒸服，或与人参、熟地黄、胡桃肉等同入配伍。   ","dosage":"5～15g","effect":"补肾益精，养阴润肺。   ","name":"哈蟆油","nature":"甘、咸，平。归肺、肾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"5～15g，用水浸泡，炖服，或作丸剂服。   "},{"cat":"补阴药","caution":"","classic":"附药：铁皮石斛  本品为兰科植物铁皮石斛Dendrobium officinale Kimura et Migo的干燥茎。性味甘，微寒；归胃、肾经。功能益胃生津，滋阴清热。适用于热病津伤，口干烦渴，胃阴不足，食少干呕，病后虚热不退，阴虚火旺，骨蒸劳热，目暗不明，筋骨痿软。煎服，6～12g。本品能敛邪，故温热病不宜早用；又能助湿，若湿温热尚未化燥伤津者忌服。","dosage":"6～12g","effect":"益胃生津，滋阴清热","name":"铁皮石斛","nature":"甘，微寒；归胃、肾经","parent":"石斛","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，6～12g"},{"cat":"补阴药","caution":"","classic":"附药：龟甲胶  本品为龟甲经水煎煮、浓缩制成的固体胶。性味咸、甘，凉；归肝、肾、心经。功能滋阴，养血，止血。适用于阴虚潮热，骨蒸盗汗，腰膝酸软，血虚萎黄，崩漏带下。3～9g，烊化兑服。","dosage":"","effect":"滋阴，养血，止血","name":"龟甲胶","nature":"咸、甘，凉；归肝、肾、心经","parent":"龟甲","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""},{"cat":"固表止汗药","caution":"","classic":"附药：小麦  本品为禾本科植物小麦Triticumaestivum L.的干燥成熟果实。性味甘，微寒；归心经。功能养心除烦。主治心神不宁，烦躁失眠及妇人脏躁证。煎服，30～60g。","dosage":"30～60g","effect":"养心除烦","name":"小麦","nature":"甘，微寒；归心经","parent":"浮小麦","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，30～60g"},{"cat":"固表止汗药","caution":"","classic":"1.自汗，盗汗 本品甘平质轻，能固表止汗，且有益胃生津之功。用于各种虚汗兼有口渴者尤宜。治气虚自汗，可单用煎服；或与黄芪、白术、浮小麦等药同用。治阴虚盗汗，可与生地黄、地骨皮、麻黄根等药配伍。   2.虚热不退，骨蒸潮热 本品能退虚热，益胃生津。常用于虚热不退，骨蒸潮热，以及病后阴虚口渴者，可与沙参、麦冬、地骨皮等药同用。   ","dosage":"30～60g","effect":"固表止汗，益胃生津，退虚热。   ","name":"糯稻根","nature":"甘，平。归肺、胃、肾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，30～60g。   "},{"cat":"固精缩尿止带药","caution":"","classic":"本品为睡莲科植物莲Nelumbo nucifera Gaertn.的干燥雄蕊。性味甘、涩，平；归心、肾经。功能固肾涩精。适用于遗精滑精，带下，尿频。煎服，3～5g。  ","dosage":"3～5g","effect":"固肾涩精","name":"莲须","nature":"甘、涩，平；归心、肾经","parent":"莲子","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～5g"},{"cat":"固精缩尿止带药","caution":"","classic":"本品为睡莲科植物莲Nelumbo nucifera Gaertn.的干燥花托。性味苦、涩，温；归肝经。功能化瘀止血。适用于崩漏，尿血，痔疮出血，产后瘀阻，恶露不尽。煎服，5～10g。炒炭用。  ","dosage":"5～10g","effect":"化瘀止血","name":"莲房","nature":"苦、涩，温；归肝经","parent":"莲子","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，5～10g"},{"cat":"固精缩尿止带药","caution":"","classic":"本品为睡莲科植物莲Nelumbo nucifera Gaertn.的成熟种子中的干燥幼叶及胚根。性味苦，寒；归心、肾经。功能清心安神，交通心肾，涩精止血。适用于热入心包，神昏谵语，心肾不交，失眠遗精，血热吐血。煎服，2～5g。  ","dosage":"2～5g","effect":"清心安神，交通心肾，涩精止血","name":"莲子心","nature":"苦，寒；归心、肾经","parent":"莲子","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，2～5g"},{"cat":"固精缩尿止带药","caution":"","classic":"本品为睡莲科植物莲Nelumbo nucifera Gaertn.的干燥叶。性味苦，平；归肝、脾、胃经。功能清暑化湿，升发清阳，凉血止血。适用于暑热烦渴，暑湿泄泻，脾虚泄泻，血热吐衄，便血崩漏。煎服，3～10g。荷叶炭收涩化瘀止血，适用于出血症和产后血晕，煎服，3～6g。  ","dosage":"3～10g","effect":"清暑化湿，升发清阳，凉血止血","name":"荷叶","nature":"苦，平；归肝、脾、胃经","parent":"莲子","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～10g"},{"cat":"固精缩尿止带药","caution":"","classic":"本品为睡莲科植物莲Nelumbo nucifera Gaertn.的干燥叶柄及花柄。性味苦，平；归肺、脾、胃经。功能通气宽胸，和胃安胎。主治外感暑湿、胸闷不畅、妊娠呕吐、胎动不安。煎服，10～15g。  ","dosage":"10～15g","effect":"通气宽胸，和胃安胎","name":"荷梗","nature":"苦，平；归肺、脾、胃经","parent":"莲子","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，10～15g"},{"cat":"固精缩尿止带药","caution":"","classic":"本品为睡莲科植物莲Nelumbo nucifera Gaertn.老熟的果实。10月间当莲子成熟时，割下莲蓬，取出果实晒干，或于整修池塘时拾取落于淤泥中之莲实，洗净，晒干。性味甘、涩、微苦，寒；归脾、胃、心经。功能清湿热，开胃进食，清心宁神，涩精止遗。适用于噤口痢，呕吐不食，心烦失眠，遗精，尿浊，带下。煎服，9～12g。虚寒久痢忌服。","dosage":"9～12g","effect":"清湿热，开胃进食，清心宁神，涩精止遗","name":"石莲子","nature":"甘、涩、微苦，寒；归脾、胃、心经","parent":"莲子","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～12g"},{"cat":"固精缩尿止带药","caution":"","classic":"1.遗精滑精，遗尿尿频 本品味苦涩性收敛，主入肾经，长于固精缩尿。适用于肾虚精关不固之遗精、滑精；肾虚膀胱失约之遗尿、尿频。可单用炒炙研末服，或与益智仁、龙骨、金樱子等药同用。   2.便血，痔血 本品功能收敛止血，善治下焦出血证。治肠风下血，可与木贼、防风等同用；治痔漏，常与地榆、槐角等同用。   3.胃痛，呕吐 本品能化瘀止痛。治胃痛日久，气血瘀滞兼呕吐者，可单用焙干研末黄酒送服，或与延胡索、香附等药同用。   ","dosage":"3～10g","effect":"固精缩尿，收敛止血，化瘀止痛。   ","name":"刺猬皮","nature":"苦、涩，平。归肾、胃、大肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～10g；研末服1.5～3g。   "},{"cat":"固精缩尿止带药","caution":"","classic":"1.吐血，崩漏，便血，痔血 本品甘涩性凉，具收敛凉血止血之功。治血热妄行之崩漏，常与牡丹皮、苎麻根、茜草等药同用；若与黄芪、山茱萸、炮姜等药同用，则可用于冲任虚寒之崩漏。治血热便血、痔血，常与地榆、槐花、黄芩炭等药同用。   2.赤白带下 本品味涩性凉，能收敛止带，为治疗带下证之常用药。治脾虚带下，常与白术、茯苓、芡实等药同用。治湿热带下，常与黄柏、车前子等药同用。   3.久痢不止，赤白下痢 本品有凉血涩肠止痢之功。治久痢不止者，常与椿皮、石榴皮、罂粟壳等药同用。治赤白下痢，可单用酒煎服，或与黄连、黄柏、秦皮等药同用。   ","dosage":"6～12g","effect":"收敛止血，止带，止痢。   ","name":"鸡冠花","nature":"甘、涩，凉。归肝、大肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，6～12g。   "},{"cat":"","caution":"","classic":"附药：蜀漆  本品为虎耳草科植物常山Dichroa febrifuga Lour.的嫩枝叶。本品的性味归经、功效、应用、使用注意与常山相同，而涌吐之力较常山为强。煎服，3～6g。","dosage":"3～6g","effect":"","name":"蜀漆","nature":"归经、功效、应用、使用注意与常山相同，而涌吐之力较常山为强","parent":"常山","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g"},{"cat":"","caution":"孕妇、体虚、心脏病、吐血、咳血、胃弱及上部无实邪者忌用。   ","classic":"1.风痰、宿食停滞，食物中毒 本品味苦涌泄，能催吐壅塞之痰，或未化之食，或误食之毒物。凡宿食停滞胃脘，胸脘痞硬，气逆上冲者，或误食毒物不久，尚停留于胃者，皆可单用本品取吐，或与赤小豆为散，用香豉煎汁和服，共奏涌吐之效，如瓜蒂散（《伤寒论》）；若风痰内扰，上蒙清窍，发为癫痫，发狂欲走者，或痰涎涌喉，喉痹喘息者，亦可单用本品为末取吐。   2.湿热黄疸 本品能祛湿退黄，用于湿热黄疸，多单用本品研末吹鼻，令鼻中黄水出而达祛湿退黄之效，如《千金翼方》以本品为细末，纳鼻中，治疗黄疸目黄不除；本品也可内服，如《金匮要略》以一味瓜蒂锉末，水煎去渣顿服，治疗诸黄。   ","dosage":"5～5g","effect":"涌吐痰食，祛湿退黄。   ","name":"甜瓜蒂","nature":"苦，寒；有毒。归胃、胆经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，2.5～5g；入丸散服，每次0.3～1g。外用适量，研末吹鼻，待鼻中流出黄水即可停药。   "},{"cat":"","caution":"本品体虚及孕妇禁服；不宜与人参、党参、西洋参、南沙参、北沙参、丹参、玄参、苦参、细辛、白芍、赤芍同用；因其治疗量与中毒量接近，内服易产生毒性反应，现代临床已不作为涌吐药使用，而主要作为农作物及蚊蝇的杀虫剂。   ","classic":"1.中风、癫痫、喉痹、误食毒物 本品内服催吐作用强，善于涌吐风痰，用治中风、癫痫、喉痹诸证见痰涎壅盛者，以及误食毒物，可与瓜蒂、防风研末为散服，以涌吐风痰，如三圣散（《儒门事亲》）；治诸风痰饮，可与郁金研末，温浆水和服探吐；治中风不语，喉中如曳锯，口中涎沫，可配天南星研末为丸，温酒服。   2.疥癣，白秃，头虱，体虱 本品外用能杀虫止痒，治疥癣、白秃，以本品研末，油调涂之。治诸疡疮，经久生虫，可配伍白矾、松脂、雄黄、苦参等，先以藜芦、苦参为末，入猪脂，煎沸，去渣，入他药末搅匀，外涂患处，如藜芦散（《圣惠方》）；治头虱，可用藜芦研末掺毛发。  此外，对蚊蝇及其幼虫有杀灭作用，也可作农作物杀虫剂使用。   ","dosage":"6g","effect":"涌吐风痰，杀虫。   ","name":"藜芦","nature":"苦、辛，寒；有毒。归肺、肝、胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"内服0.3～0.6g，入丸散，温水送服以催吐；外用适量，研末，油调涂。   "},{"cat":"","caution":"","classic":"1.湿疹，疥癣，脱肛，痔疮，疮疡，聤耳流脓 本品酸涩性寒，外用善于解毒杀虫，收湿止痒，尤宜于疮面湿烂或瘙痒者。治湿疹瘙痒，可与雄黄为末，浓茶调敷，如二味拔毒散（《医宗金鉴》）；治疥癣瘙痒，可与硫黄、轻粉等同用，如白矾散（《证治准绳》）；治疔肿恶疮，可与黄丹研末外用，如二仙散（《卫生宝鉴》）；治口疮、聤耳、鼻息肉、酒齄鼻者，可单用或配伍硫黄、乳香等同用。治疗痔疮，可与五倍子、地榆、槐花等煎汤熏洗患处。   2.便血、衄血、崩漏 本品性涩，能入肝经血分，有收敛止血作用，可用治多种出血证。治衄血不止，《圣济总录》以枯矾研末吹鼻；治崩漏，可与五倍子、地榆同用；治金疮出血，用生矾、煅矾配松香研末，外敷伤处。   3.久泻久痢 本品具有涩肠止泻作用，治疗久泻久痢，可与诃子、肉豆蔻等配伍。   4.癫痫发狂 本品酸苦涌泄而能祛除风痰，治痰壅心窍，癫痫发狂，常与郁金为末，薄荷糊丸服，如白金丸（《本事方》）。  此外，本品还用治湿热黄疸，可与硝石配伍，治女劳疸，如硝石散（《金匮要略》）。   ","dosage":"5g","effect":"外用解毒杀虫，燥湿止痒；内服止血止泻，祛除风痰。   ","name":"白矾","nature":"酸、涩，寒。归肺、脾、肝、大肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"内服，0.6～1.5g，入丸散剂。外用适量，研末敷或化水洗患处。   "},{"cat":"","caution":"","classic":"附药：皂矾（绿矾）  本品为硫酸盐类矿物水绿矾的矿石。主含含水硫酸亚铁（FeSO4 ·7H2 O）。性味酸，凉；归肝、脾经。功能解毒燥湿，杀虫补血。适用于黄肿胀满，疳积久痢，肠风便血，血虚萎黄，湿疮疥癣，喉痹口疮。煎服，0.8～1.6g；外用适量。孕妇慎用。","dosage":"6g","effect":"解毒燥湿，杀虫补血","name":"皂矾","nature":"酸，凉；归肝、脾经","parent":"白矾","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，0.8～1.6g；外用适量"},{"cat":"","caution":"只供外用，不可内服。   ","classic":"1.体癣，手足癣，头癣 本品外用有较好的杀虫疗癣、祛湿止痒作用。治疗体癣，手足癣，头癣，可单用浸酒涂擦或研末加醋调敷。现多制成10%～50%的土槿皮酊，或配合水杨酸、苯甲酸等制成复方土槿皮酊外用，如鹅掌风药水（《中国药物大全》）。   2.疥疮，湿疹，皮炎，皮肤瘙痒 本品外用能杀虫止痒，治疗疥疮，湿疹，皮炎，皮肤瘙痒，可单用浸酒外擦，或与苦参、白鲜皮、黄柏等同用。   ","dosage":"","effect":"杀虫，疗癣，止痒。   ","name":"土荆皮","nature":"辛，温；有毒。归肺、脾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"外用适量，醋或酒浸涂擦，或研末调涂患处。   "},{"cat":"","caution":"","classic":"附药：木槿皮  本品为锦葵科植物木槿Hibiscus syriacus L.的干燥茎皮或根皮。性味甘、苦，微寒；归大肠、肝、脾经。功能清热利湿，杀虫止痒。适用于湿热泻痢，肠风下血，脱肛，痔疮，赤白带下，阴道滴虫病，皮肤疥癣，阴囊湿疹。外用适量，酒浸涂搽或煎水熏洗；煎服，3～9g。无湿热者慎服。","dosage":"3～9g","effect":"清热利湿，杀虫止痒","name":"木槿皮","nature":"甘、苦，微寒；归大肠、肝、脾经","parent":"土荆皮","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～9g"},{"cat":"","caution":"","classic":"1.疮疡肿毒，乳痈，瘰疬，癌肿 本品能攻毒杀虫，攻坚破积，为外科常用之品。虽可单用，但更常与解毒消肿生肌药配伍应用。治疮肿初发，《证治准绳》以之与生南星、生草乌、白矾等共为细末，米醋调涂。治瘰疬，《圣惠方》以之与蛇蜕、黄芪、黄丹等为膏外用。治癌肿，可与莪术、全蝎、僵蚕等配伍。   2.皮肤顽癣，鹅掌风，牙痛，风湿痹痛 本品质轻，且性善走窜，能祛风止痛、止痒。用治风疹瘙痒，可与蝉蜕、防风等同用。若治顽癣瘙痒，以新鲜露蜂房烧灰存性，配伍白矾、樟脑，米醋调糊外涂。治风虫牙痛，可与细辛水煎漱口用，《普济方》中即载有十余首以蜂房为主的治牙痛方。治风湿痹痛，可与川乌、草乌同用，酒精浸泡外涂痛处；或与全蝎、蜈蚣、土鳖虫各等分，研末为丸服。   ","dosage":"3～5g","effect":"攻毒杀虫，祛风止痛。   ","name":"蜂房","nature":"甘，平。归胃经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～5g。外用适量，研末油调敷患处，或煎水漱口，或洗患处。   "},{"cat":"","caution":"","classic":"附药：蜂蜡  本品为蜜蜂科昆虫中华蜜蜂 Apis cerana Fabricius 或意大利蜜蜂 Apis mellifera Linnaeus 分泌的蜡。性味甘，微温；归脾经。功能解毒，敛疮，生肌，止痛。外用于溃疡不敛，臁疮糜烂，外伤破溃，烧烫伤。外用适量，熔化敷患处；常作成药赋形剂及油膏基质。","dosage":"","effect":"解毒，敛疮，生肌，止痛","name":"蜂蜡","nature":"甘，微温；归脾经","parent":"蜂房","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""},{"cat":"","caution":"气虚阴亏、有热者及孕妇忌服。   ","classic":"1.疥癣瘙痒，湿疮溃烂 本品辛热燥烈，外用能除湿杀虫、消肿止痒。用治疥癣，常与土槿皮、川椒、白矾等外用。治臁疮，《经验广方》以本品加猪脂油、葱白适量，共捣烂，敷患处。若治瘰疬溃烂，《外科全生集》以之与雄黄等分为末，用时先以荆芥煎汤洗患处，再用麻油调涂。   2.跌打伤痛，牙痛 借其辛烈行散，消肿止痛之力以取效。治跌打伤痛，肌肤完好者，可泡酒外擦。治龋齿牙痛，《余居士选奇方》以之与皂角（去皮、核）各等分为末，蜜丸，塞孔中。   3.痧胀腹痛，吐泻神昏 樟脑辛香走窜，有开窍醒神，辟秽化浊，温散止痛之功。治感受秽浊疫疬或暑湿之邪，而致腹痛闷乱、吐泻昏厥诸证，《本草正义》以本品与没药、乳香（1∶2∶3） 共为细末，用时以茶水调服。   ","dosage":"2g","effect":"除湿杀虫，温散止痛，开窍辟秽。   ","name":"樟脑","nature":"辛，热；有毒。归心、脾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"外用适量，研末撒布或调敷。内服0.1～0.2g，入散剂或用酒溶化服。   "},{"cat":"","caution":"","classic":"本品为蟾蜍科动物中华大蟾蜍Bufo bufo gargarizans Cantor或黑眶蟾蜍Bufo melanostictus Schneider的皮。其味辛，性凉，有小毒。功能清热解毒，利水消胀。适用于痈疽疮毒、疳积腹胀、瘰疬肿瘤等病证。煎服，3～6g；研末入丸散服，每次0.3～0.9g。外用适量，可研末调敷患处，或以新鲜蟾皮外贴患处。  ","dosage":"3～6g","effect":"清热解毒，利水消胀","name":"蟾皮","nature":"","parent":"蟾酥","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，3～6g；研末入丸散服，每次0.3～0.9g"},{"cat":"","caution":"","classic":"本品为壁虎科动物无蹼壁虎Gekko swinhoana Gunther或其他几种壁虎的干燥全体。性味咸、寒，有小毒；归肝、心经。功能祛风定惊，散结止痛。适用于风湿痹痛，中风瘫痪，破伤风，惊痫，瘰疬，痈疮，癌肿。煎服，2～5g；研末吞服，每次1～1.5g。外用适量，研末调敷。血虚气弱者不宜服。","dosage":"2～5g","effect":"祛风定惊，散结止痛","name":"守宫","nature":"咸、寒，有小毒；归肝、心经","parent":"蟾酥","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，2～5g；研末吞服，每次1～1.5g"},{"cat":"","caution":"外用可引起皮肤发红、灼热甚至起泡，故不可敷之过久。阴虚火旺及有目、舌、喉、口齿诸疾不宜服用。孕妇忌灌肠用。   ","classic":"1.痈肿疮疡，疥癣 大蒜外用或内服，均有解毒，杀虫，消肿作用。治背疽漫肿无头者，《外科精要》以本品配伍淡豆豉、乳香研烂置疮上，铺艾灸之。民间亦有用大蒜切片外擦或捣烂外敷，治疗皮肤或头癣瘙痒。   2.肺痨，顿咳，痢疾，泄泻 本品解毒，杀虫，可单独或配伍入复方中使用。如验方以大蒜煮粥送服白及粉治肺痨咳血、顿咳。治泻痢，可单用或以10%大蒜浸液保留灌肠。大蒜还可用于防治流感、流脑、乙脑等流行性传染病。   3.蛲虫病，钩虫病 本品有杀虫作用。治蛲虫病可将大蒜捣烂，加茶油少许，睡前涂于肛门周围。如将大蒜捣烂，在下田前涂抹四肢，有预防钩虫感染的作用。  此外，大蒜还能健脾温胃，增强食欲，用治脘腹冷痛，食欲减退或饮食不消。   ","dosage":"9～15g","effect":"解毒消肿，杀虫，止痢。   ","name":"大蒜","nature":"辛，温。归脾、胃、肺经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"煎服，9～15g。外用适量，捣烂外敷，或切片外擦，或隔蒜灸。   "},{"cat":"","caution":"本品有大毒，只可外用，不可内服；外用亦不宜久用；孕妇禁用。   ","classic":"痈疽疔疮，梅毒下疳，一切恶疮，肉暗紫黑，腐肉不去，窦道瘘管，脓水淋漓，久不收口 本品有较好的拔毒除脓、去腐生肌作用，为外科要药，但有大毒，只供外用。常与煅石膏研末外用，根据病情不同而调整两药的用量比例。如红粉与煅石膏的用量比为1∶9者，称九一丹，拔毒力较轻而生肌力较强；比例为2∶8者，称八二丹；比例为3∶7者，称七三丹；比例为1∶1者，称五五丹；比例为9∶1者，称九转丹；随着本品用量的增加，则拔毒除脓之力逐渐增强。   ","dosage":"","effect":"拔毒，除脓，去腐，生肌。   ","name":"红粉","nature":"辛，热；有大毒。归肺、脾经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"外用适量，研极细粉单用或与其他药味配制成散剂或制成药捻。   "},{"cat":"","caution":"本品有毒，不可过量或久服；内服宜慎；孕妇禁服。   ","classic":"1.疥疮，顽癣，臁疮，梅毒，疮疡，湿疹 本品辛寒有毒，性烈，有较强的攻毒杀虫止痒、生肌敛疮作用。治疗疥疮，与黄柏、蛤粉、煅石膏共为细末，凉水或麻油调涂，如蛤粉散（《外科正宗》）。治疗臁疮不合，配黄连末、猪胆汁调涂。治疗干湿癣，与铅丹、硫黄为细末，生油调涂，如如圣散（《圣济总录》）。   2.痰涎积滞，水肿鼓胀，二便不利 本品入大肠、小肠经，内服能通利二便，逐水退肿。治疗邪盛正气未衰之水肿胀满、二便不利，常与甘遂、大戟、大黄等峻下逐水药同用，如舟车丸（《丹溪心法》）。   ","dosage":"2g","effect":"外用杀虫，攻毒，敛疮；内服祛痰消积，逐水通便。   ","name":"轻粉","nature":"辛，寒；有毒。归大肠、小肠经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"外用适量，研末掺敷患处。内服每次0.1～0.2g，每日1～2次，多入丸剂或装胶囊服。服后及时漱口，以免口腔糜烂。   "},{"cat":"","caution":"","classic":"附药：水银  本品为自然元素类液态矿物自然汞，主要从辰砂矿经加工提炼制成。主产于贵州、湖南、湖北等地。性味辛，寒，有毒；归心、肝、肾经。功能杀虫，攻毒。适用于疥癣，梅毒，恶疮，痔瘘。外用适量，涂擦。本品有毒，不宜内服，孕妇禁用。外用亦不可长期或过量使用，用于溃疡创面时，尤须注意，以免吸收中毒。不宜与砒霜（砒石）同用。","dosage":"","effect":"杀虫，攻毒","name":"水银","nature":"辛，寒，有毒；归心、肝、肾经","parent":"轻粉","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""},{"cat":"","caution":"本品有剧毒，内服宜慎；外用亦应注意，以防局部吸收中毒。不可作酒剂服。体虚者及孕妇禁服。不宜与水银同用。   ","classic":"1.恶疮，瘰疬，顽癣，牙疳，痔疮 本品外用有攻毒杀虫、蚀疮去腐之功。虽可单用贴敷，因易中毒且引起剧烈疼痛，故多配伍其他药物以缓其毒。治疗恶疮日久，可与硫黄、苦参、附子、蜡等同用，调油为膏，柳枝煎汤洗疮后外涂，如砒霜膏（《圣惠方》）。治疗瘰疬、顽癣、牙疳、疔疮，与明矾、雄黄、乳香共为细末，如三品一条枪（《外科正宗》）。   2.寒痰哮喘 本品味辛性大热，入肺经，内服能祛寒劫痰平喘。治疗寒痰喘咳，久治不愈，可与淡豆豉为丸服，如紫金丹（《普济本事方》）。   3.癌肿 本品有大毒，能以毒攻毒以抑癌，用治多种癌症。   ","dosage":"004g","effect":"外用攻毒杀虫，蚀疮去腐；内服劫痰平喘，攻毒抑癌。   ","name":"砒石","nature":"辛，大热；有大毒。归肺、脾、肝经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"外用适量，研末撒敷，宜作复方散剂或入膏药、药捻用。内服宜入丸、散，每次0.002～0.004g。   "},{"cat":"","caution":"本品有毒，用之不当可引起铅中毒，宜慎用；亦不可持续使用以防蓄积中毒。孕妇禁用。   ","classic":"1.疮疡溃烂，湿疹瘙痒，疥癣 本品味辛咸性寒，有毒，外用有拔毒化腐生肌、收湿杀虫止痒之功。治疗疮疡初起红肿或脓成未溃者，配黄明胶，如敛疮内消方（《普济本事方》）。治疗痈疽溃后不敛，配伍煅石膏、轻粉、冰片，研细末，外掺疮上，如桃花散（《马氏方》）。治疗湿疹，疥癣，可与轻粉、黄连、黄柏等同用，共研细末，如金华散（《婴童百问》）。   2.惊痫癫狂，心神不宁 本品质重，性沉降，咸走血分，入心经，能镇心安神，用治惊痫癫狂，心神不宁。但因其有毒，易致蓄积性中毒，故内服宜慎。  此外，铅丹又为制备外用膏药的重要原料，常与植物油或解毒、活血、生肌药熬制成外贴膏药应用。   ","dosage":"6g","effect":"外用拔毒生肌，杀虫止痒；内服坠痰镇惊。   ","name":"铅丹","nature":"辛、咸，寒；有毒。归心、脾、肝经。   ","parent":"","processing":"","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":"外用适量，研末撒布或熬膏贴敷。内服多入丸、散，0.3～0.6g。   "},{"cat":"","caution":"","classic":"附药：密陀僧  本品为铅矿石冶炼而成，主含氧化铅（PbO）。主产于湖南、江苏。性味咸、辛，平；有毒；归肝、脾经。外用杀虫收敛，内服祛痰镇惊。外用治疗痔疮，湿疹湿疮，溃疡不敛，疥癣，狐臭；内服用于风痰惊痫。外用适量，研末撒或调涂，或制成膏药、软膏、油剂等外用；内服，入丸、散，0.2～0.5g。本品用之不当可引起铅中毒，不可持续使用以防蓄积中毒，内服宜慎；孕妇、儿童应禁用；不宜与狼毒同用。","dosage":"","effect":"","name":"密陀僧","nature":"咸、辛，平；有毒；归肝、脾经","parent":"铅丹","processing":"附药","py":"","source":"《中药学》（全国中医药行业“十三五”规划教材）","usage":""}];
